import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import {
  spread, sampleIdx, keepRow, betweenShare, shuffled, buildRows, percentile,
} from './testsLabLogic';

// Interactive versions of the tests in the paper. Data: public/data/tests_lab.json.

const W = 700, H = 480;
const LAT0 = 52.8, LAT1 = 44.0, LON0 = 22.0, LON1 = 40.6;
const px = (lon) => ((lon - LON0) / (LON1 - LON0)) * W;
const py = (lat) => ((LAT0 - lat) / (LAT0 - LAT1)) * H;
function Shape({ q, shape, color, w }) {
  const cx = px(q.lon0), cy = py(q.lat0);
  if (shape === 'circle') return <circle cx={cx} cy={cy} r={q.circ * KM_PX} fill="none" stroke={color} strokeWidth={w} strokeDasharray="6 4" />;
  return <ellipse cx={cx} cy={cy} rx={q.ra * KM_PX} ry={q.rb * KM_PX} transform={`rotate(${-q.theta} ${cx} ${cy})`} fill="none" stroke={color} strokeWidth={w} strokeDasharray="6 4" />;
}
const KM_PX = W / ((LON1 - LON0) * Math.cos((48 * Math.PI) / 180) * 111.32);
export const C = { blue: '#3987e5', orange: '#d95926', aqua: '#199e70', grey: '#6b6a66', pale: '#c3c2b7', white: '#f2f3f5' };
export const fmt = (x, d = 3) => (x == null || Number.isNaN(x) ? '–' : x.toFixed(d));
export const pct = (x, d = 1) => `${(x * 100).toFixed(d)}%`;

// ---------- shared pieces ---------------------------------------------------
export function Hist({ values, marks = [], xmin, xmax, bins = 30, xlabel, width = 560, height = 220, unit = '' }) {
  const m = { l: 36, r: 14, t: 18, b: 40 };
  const iw = width - m.l - m.r, ih = height - m.t - m.b;
  const sx = (v) => m.l + ((v - xmin) / (xmax - xmin)) * iw;
  const counts = new Array(bins).fill(0);
  for (const v of values) {
    const b = Math.min(bins - 1, Math.max(0, Math.floor(((v - xmin) / (xmax - xmin)) * bins)));
    counts[b] += 1;
  }
  const cmax = Math.max(1, ...counts);
  const ticks = 5;
  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="tl-hist" role="img" aria-label={xlabel}>
      {counts.map((c, i) => {
        const x0 = sx(xmin + (i / bins) * (xmax - xmin)), x1 = sx(xmin + ((i + 1) / bins) * (xmax - xmin));
        const h = (c / cmax) * ih;
        return <rect key={i} x={x0 + 0.5} y={m.t + ih - h} width={Math.max(0, x1 - x0 - 1)} height={h} rx="1.5" fill={C.grey} opacity="0.85" />;
      })}
      <line x1={m.l} x2={width - m.r} y1={m.t + ih} y2={m.t + ih} stroke="#3a4048" />
      {Array.from({ length: ticks + 1 }, (_, i) => {
        const v = xmin + (i / ticks) * (xmax - xmin);
        return (
          <g key={i}>
            <line x1={sx(v)} x2={sx(v)} y1={m.t + ih} y2={m.t + ih + 4} stroke="#3a4048" />
            <text x={sx(v)} y={m.t + ih + 16} textAnchor="middle" className="tl-tick">{Math.abs(xmax) < 2 ? v.toFixed(2) : Math.round(v)}{unit}</text>
          </g>
        );
      })}
      <text x={m.l + iw / 2} y={height - 6} textAnchor="middle" className="tl-axis">{xlabel}</text>
      {marks.map((mk, i) => (
        <g key={i}>
          <line x1={sx(mk.x)} x2={sx(mk.x)} y1={m.t - 4} y2={m.t + ih} stroke={mk.color} strokeWidth="2.2" />
          <text x={Math.min(Math.max(sx(mk.x), m.l + 30), width - m.r - 30)} y={m.t - 6} textAnchor="middle" className="tl-marklabel" fill={mk.color}>{mk.label}</text>
        </g>
      ))}
    </svg>
  );
}

export function Panel({ n, title, children, lead }) {
  return (
    <section className="tl-panel">
      <h2><span className="tl-n">{n}</span> {title}</h2>
      {lead && <p className="tl-lead">{lead}</p>}
      {children}
    </section>
  );
}

export function useAnimator() {
  const timer = useRef(null);
  useEffect(() => () => clearTimeout(timer.current), []);
  return {
    loop(step, done) {
      clearTimeout(timer.current);
      const tick = () => { if (step()) timer.current = setTimeout(tick, 16); else if (done) done(); };
      tick();
    },
    stop() { clearTimeout(timer.current); },
  };
}

const outlinePath = (rings) => (rings || []).map((r) => 'M' + r.map(([la, lo]) => `${px(lo).toFixed(1)},${py(la).toFixed(1)}`).join('L') + 'Z').join('');
const gridLines = () => {
  const out = [];
  for (let lon = 24; lon <= 40; lon += 4) out.push(<line key={`x${lon}`} x1={px(lon)} x2={px(lon)} y1="0" y2={H} className="tl-grid" />);
  for (let lat = 46; lat <= 52; lat += 2) out.push(<line key={`y${lat}`} y1={py(lat)} y2={py(lat)} x1="0" x2={W} className="tl-grid" />);
  for (let lon = 24; lon <= 40; lon += 4) out.push(<text key={`tx${lon}`} x={px(lon) + 3} y={H - 5} className="tl-tick">{lon}°E</text>);
  for (let lat = 46; lat <= 52; lat += 2) out.push(<text key={`ty${lat}`} x="4" y={py(lat) - 3} className="tl-tick">{lat}°N</text>);
  return out;
};

// ---------- 1 · compactness ---------------------------------------------------
const KIND = 'theme'; // the lab works on subject headings (themes), as in the paper
const LEVEL_LABEL = ['All places', 'Non-generic places (as in the paper)', 'Also without region centres'];

function Compactness({ data }) {
  const kind = KIND;
  const [level, setLevel] = useState(1);
  const [cid, setCid] = useState(null);
  const [nulls, setNulls] = useState([]);
  const [sample, setSample] = useState(null);
  const [running, setRunning] = useState(false);
  const [measure, setMeasure] = useState('axes');
  const [nulls2, setNulls2] = useState([]);
  const shape = measure === 'circle' ? 'circle' : 'ellipse';
  const two = measure === 'axes';
  const stat = (q) => (measure === 'circle' ? q.circ : measure === 'elong' ? q.elong : two ? q.ra : q.radius);
  const stat2 = (q) => q.rb;
  const isE = measure === 'elong';
  const unitS = isE ? '' : ' km';
  const fm = (v) => (isE ? v.toFixed(2) : String(Math.round(v)));
  const anim = useAnimator();

  const set = data.compact[kind];
  const pool = useMemo(() => set.pool.filter((p) => keepRow(p[4], level)), [set, level]); // every place once, weighted by its books
  const themeRows = useMemo(() => set.pts.filter((p) => keepRow(p[4], level)), [set, level]);
  const clusters = useMemo(() => {
    const cnt = {};
    for (const p of themeRows) cnt[p[3]] = (cnt[p[3]] || 0) + 1;
    return set.clusters.filter((c) => (cnt[c.id] || 0) >= 6).sort((a, b) => b.n - a.n).map((c) => ({ ...c, rows: cnt[c.id] }));
  }, [themeRows, set]);
  useEffect(() => { if (!clusters.find((c) => c.id === cid)) setCid(clusters.length ? clusters[0].id : null); }, [clusters, cid]);
  useEffect(() => { anim.stop(); setRunning(false); setNulls([]); setNulls2([]); setSample(null); }, [level, cid, measure]); // eslint-disable-line

  const members = useMemo(() => themeRows.filter((p) => p[3] === cid), [themeRows, cid]);
  const obs = useMemo(() => (members.length >= 3 ? spread(members.map((p) => p[0]), members.map((p) => p[1]), members.map((p) => p[2])) : null), [members]);
  const k = members.length;

  const draw = () => {
    const ix = sampleIdx(pool.length, k);
    const rows = ix.map((j) => pool[j]);
    const s = spread(rows.map((p) => p[0]), rows.map((p) => p[1]), rows.map((p) => p[2]));
    return { rows, s };
  };
  const one = () => {
    const d = draw();
    setSample(d);
    if (d.s) { setNulls((a) => a.concat(stat(d.s))); setNulls2((a) => a.concat(stat2(d.s))); }
  };
  const many = (total) => {
    setRunning(true);
    let done = 0;
    anim.loop(() => {
      const batch = [], batch2 = [];
      let last = null;
      for (let i = 0; i < 12 && done < total; i++, done++) { const d = draw(); last = d; if (d.s) { batch.push(stat(d.s)); batch2.push(stat2(d.s)); } }
      setNulls((a) => a.concat(batch)); setNulls2((a) => a.concat(batch2)); if (last) setSample(last);
      return done < total;
    }, () => setRunning(false));
  };
  const reset = () => { anim.stop(); setRunning(false); setNulls([]); setNulls2([]); setSample(null); };

  const sorted2 = useMemo(() => nulls2.slice().sort((a, b) => a - b), [nulls2]);
  const pTwoOf = (arr, v) => { const n = arr.length; if (!n) return null; const lo = (arr.filter((x) => x <= v).length + 1) / (n + 1), hi = (arr.filter((x) => x >= v).length + 1) / (n + 1); return Math.min(1, 2 * Math.min(lo, hi)); };
  const pctLE = (arr, v) => Math.round((arr.filter((x) => x <= v).length / arr.length) * 100);
  const sorted = useMemo(() => nulls.slice().sort((a, b) => a - b), [nulls]);
  const nn = sorted.length;
  const pc = obs ? (sorted.filter((v) => v <= stat(obs)).length + 1) / (nn + 1) : null;
  const ps = obs ? (sorted.filter((v) => v >= stat(obs)).length + 1) / (nn + 1) : null;
  const pTwo = obs && nn ? Math.min(1, 2 * Math.min(pc, ps)) : null;
  const cl = clusters.find((c) => c.id === cid);
  const xmin = isE ? 1 : 0;
  const xmax = Math.max(isE ? 4 : 500, obs ? stat(obs) * 1.2 : 0, nn ? percentile(sorted, 0.995) * 1.1 : 0);
  const xmax2 = Math.max(250, obs ? obs.rb * 1.2 : 0, nn ? percentile(sorted2, 0.995) * 1.1 : 0);

  return (
    <Panel n="1" title="Is a subject heading more compact than a random set of places?"
      lead="Pick a subject heading, then draw random sets of places with the same number of places. If a subject belonged to one area, its places would sit closer together than random ones.">
      <div className="tl-toolbar">
        <label>Places <select value={level} onChange={(e) => setLevel(+e.target.value)}>{[1, 2].map((i) => <option key={i} value={i}>{LEVEL_LABEL[i]}</option>)}</select></label>
        <label>Measure <select value={measure} onChange={(e) => setMeasure(e.target.value)}><option value="axes">Ellipse: radius 1 (long) and radius 2 (short)</option><option value="radius">Ellipse: one combined radius (as in the paper)</option><option value="elong">Ellipse: elongation (long ÷ short axis)</option><option value="circle">Circle: radius</option></select></label>
        <label className="tl-grow">Subject heading <select value={cid ?? ''} onChange={(e) => setCid(+e.target.value)}>{clusters.map((c) => <option key={c.id} value={c.id}>{c.label} ({c.n} books, {c.rows} places)</option>)}</select></label>
      </div>
      <div className="tl-row">
        <div className="tl-col tl-map">
          <svg viewBox={`0 0 ${W} ${H}`} className="tl-svg">
            {gridLines()}
            <path d={outlinePath(data.outline)} className="tl-outline" />
            {pool.map((p, i) => <circle key={i} cx={px(p[1])} cy={py(p[0])} r={1.8 + Math.sqrt(p[2]) * 0.25} fill={C.grey} opacity="0.25" />)}
            {sample && sample.rows.map((p, i) => <circle key={`s${i}`} cx={px(p[1])} cy={py(p[0])} r={2.6 + Math.sqrt(p[2]) * 0.3} fill={C.orange} opacity="0.75" />)}
            {sample && sample.s && <Shape q={sample.s} shape={shape} color={C.orange} w="2" />}
            {members.map((p, i) => <circle key={`m${i}`} cx={px(p[1])} cy={py(p[0])} r={2.6 + Math.sqrt(p[2]) * 0.3} fill={C.blue} opacity="0.9" />)}
            {obs && <Shape q={obs} shape={shape} color={C.blue} w="2.2" />}
          </svg>
          <div className="tl-legend"><span><i style={{ background: C.blue }} />the subject heading</span><span><i style={{ background: C.orange }} />latest random set</span><span><i style={{ background: C.grey }} />all places</span><span className="tl-muted">dashed {shape === 'circle' ? 'circle = a circle with the same average spread as the oval' : 'ellipse = standard deviational ellipse'}</span></div>
        </div>
        <div className="tl-col">
          <div className="tl-btns">
            <button onClick={one} disabled={running}>Draw 1 random set</button>
            <button onClick={() => many(200)} disabled={running}>Draw 200</button>
            <button onClick={() => many(1000)} disabled={running}>Draw 1,000</button>
            <button className="tl-ghost" onClick={reset}>Reset</button>
          </div>
          <Hist values={sorted} xmin={xmin} xmax={xmax} bins={32} height={two ? 190 : 220} xlabel={isE ? 'elongation of the place set (1 = round)' : measure === 'circle' ? 'circle radius of the place set, km' : two ? 'radius 1: the long radius of the oval, km' : 'combined radius of the place set, km'} unit=""
            marks={obs ? [{ x: stat(obs), color: C.blue, label: `heading ${fm(stat(obs))}${unitS}` }] : []} />
          {two && <Hist values={sorted2} xmin={0} xmax={xmax2} bins={32} height={190} xlabel="radius 2: the short radius of the oval, km" unit=""
            marks={obs ? [{ x: obs.rb, color: C.blue, label: `heading ${Math.round(obs.rb)} km` }] : []} />}
          <div className="tl-readout">
            {cl && obs && (
              <>
                {two ? (
                  <p><b>{cl.label}</b>: {k} places. Radius 1 (long) <b>{Math.round(obs.ra)} km</b>, radius 2 (short) <b>{Math.round(obs.rb)} km</b>, so the oval is {obs.elong.toFixed(1)} times as long as it is wide. Combined radius (the paper's single number) {Math.round(obs.radius)} km.</p>
                ) : (
                  <p><b>{cl.label}</b>: {k} places, {isE ? 'elongation' : measure === 'circle' ? 'circle radius' : 'combined radius'} <b>{fm(stat(obs))}{unitS}</b>{shape === 'ellipse' ? <> (radius 1 {Math.round(obs.ra)} km, radius 2 {Math.round(obs.rb)} km)</> : null}.</p>
                )}
                {nn > 0 ? (two ? (
                  <p>{nn} random sets so far. Radius 1: median <b>{Math.round(percentile(sorted, 0.5))} km</b>, {pctLE(sorted, obs.ra)}% of random sets are as short or shorter, two-sided p ≈ <b>{fmt(pTwoOf(sorted, obs.ra))}</b>. Radius 2: median <b>{Math.round(percentile(sorted2, 0.5))} km</b>, {pctLE(sorted2, obs.rb)}% are as short or shorter, two-sided p ≈ <b>{fmt(pTwoOf(sorted2, obs.rb))}</b>{nn < 200 ? ' (draw more sets for steadier values)' : ''}.</p>
                ) : (
                  <p>{nn} random sets so far, median <b>{fm(percentile(sorted, 0.5))}{unitS}</b>. {pctLE(sorted, stat(obs))}% of random sets are {isE ? 'as round or rounder' : 'as tight or tighter'}. Two-sided p ≈ <b>{fmt(pTwo)}</b>{nn < 200 ? ' (draw more sets for a steadier value)' : ''}.</p>
                )) : <p className="tl-muted">Draw random sets to see where the subject heading falls.</p>}
              </>
            )}
          </div>
        </div>
      </div>
      <p className="tl-note">A subject heading here is one heading term of the catalog (on at least 15 books, with at least six places), plus three groups assembled by hand: the nationalist underground, the Famine of 1932 to 1933 and the German occupation. In the paper this is run for all 101 headings with 1,000 random sets each, and p-values are corrected across headings: none is more compact or more spread out than chance.</p>
    </Panel>
  );
}

// ---------- 2 · classifier shuffle ---------------------------------------------
const CLF = [
  ['place|0', 'Places, all places'], ['place|1', 'Places, without generic places'], ['place|2', 'Places, also without region centres'], ['record|1', 'Books about one region, without generic places'],
];
function Classifier({ data }) {
  const [key, setKey] = useState('place|1');
  const [shown, setShown] = useState(0);
  const [running, setRunning] = useState(false);
  const anim = useAnimator();
  const d = data.classifier[key];
  useEffect(() => { anim.stop(); setRunning(false); setShown(0); }, [key]); // eslint-disable-line
  const vals = d.null.slice(0, shown);
  const sorted = vals.slice().sort((a, b) => a - b);
  const p = (sorted.filter((v) => v >= d.ba).length + 1) / (shown + 1);
  const run = (target) => {
    setRunning(true);
    anim.loop(() => { let s = 0; setShown((cur) => { s = Math.min(target, cur + 2); return s; }); return s < target; }, () => setRunning(false));
  };
  const cls = Object.entries(d.classes);
  return (
    <Panel n="2" title="Can subject headings tell west, centre, east and south apart?"
      lead="A classifier learns each region's topic profile and is scored on places or books it has not seen. Then the region labels are shuffled and the whole procedure is repeated. The shuffled scores show what guessing looks like.">
      <div className="tl-toolbar">
        <label className="tl-grow">Data set <select value={key} onChange={(e) => setKey(e.target.value)}>{CLF.map(([k2, l]) => <option key={k2} value={k2}>{l}</option>)}</select></label>
      </div>
      <div className="tl-row">
        <div className="tl-col">
          <div className="tl-btns">
            <button onClick={() => setShown((s) => Math.min(d.null.length, s + 1))} disabled={running || shown >= d.null.length}>Shuffle once</button>
            <button onClick={() => run(d.null.length)} disabled={running || shown >= d.null.length}>Shuffle all {d.null.length}</button>
            <button className="tl-ghost" onClick={() => { anim.stop(); setRunning(false); setShown(0); }}>Reset</button>
          </div>
          <Hist values={vals} xmin={0.1} xmax={0.6} bins={40} xlabel="balanced accuracy"
            marks={[{ x: 0.25, color: C.pale, label: 'guessing 0.25' }, { x: d.ba, color: C.blue, label: `real labels ${fmt(d.ba)}` }]} />
        </div>
        <div className="tl-col tl-readout">
          <p>With the real region labels the classifier scores <b>{fmt(d.ba)}</b> on {d.n} {key.startsWith('place') ? 'places' : 'books'}. Guessing among four regions scores about 0.25.</p>
          <p>{shown} shuffles so far{shown > 0 ? <>: the best shuffled score is <b>{fmt(sorted[sorted.length - 1])}</b>, the average <b>{fmt(vals.reduce((a, b) => a + b, 0) / shown)}</b>. Share of shuffles that match or beat the real score: p ≈ <b>{fmt(p)}</b>.</> : '. Press a button to start.'}</p>
          <p className="tl-muted">Region sizes: {cls.map(([k2, v]) => `${k2} ${v}`).join(', ')}. The shuffled scores were computed beforehand by running the full classifier {d.null.length} times, because each run trains a model. The real score is modest (well above 0.25, far below 1), which is what the paper means by regions differing in emphasis without being separate.</p>
        </div>
      </div>
    </Panel>
  );
}

// ---------- 3 · the Dnipro and other lines ----------------------------------------
const VPOS = Array.from({ length: 15 }, (_, i) => 23 + i);
const HPOS = [45, 45.5, 46, 46.5, 47, 47.5, 48, 48.5, 49, 49.5, 50, 50.5, 51];
function Dnipro({ data }) {
  const [mode, setMode] = useState('v');
  const [pos, setPos] = useState(26);
  const [level, setLevel] = useState('record');
  const D = data.dnipro;
  const positions = mode === 'v' ? VPOS : HPOS;
  const idx = Math.max(0, positions.indexOf(pos));
  useEffect(() => { if (mode !== 'dnipro' && !positions.includes(pos)) setPos(positions[0]); }, [mode]); // eslint-disable-line
  const sweep = D.sweep[level];
  const keyOf = (p) => (mode === 'v' ? `v${p}` : `h${p}`);
  const cur = mode === 'dnipro' ? sweep.dnipro : sweep[keyOf(pos)];
  const dn = sweep.dnipro.ba;
  const sideOf = (p) => {
    if (mode === 'dnipro') return p[5];
    if (mode === 'v') { const d = Math.abs(p[2] - pos) * Math.cos((p[1] * Math.PI) / 180) * 111.32; return d < 40 ? 0 : p[2] > pos ? 1 : -1; }
    const d = Math.abs(p[1] - pos) * 110.57; return d < 40 ? 0 : p[1] > pos ? 1 : -1;
  };
  const sides = D.points.map(sideOf);
  const nA = sides.filter((s) => s === 1).length, nB = sides.filter((s) => s === -1).length;
  const names = mode === 'dnipro' ? ['left bank', 'right bank'] : mode === 'v' ? ['east', 'west'] : ['north', 'south'];
  const river = D.river.map(([la, lo]) => `${px(lo)},${py(la)}`).join(' ');
  // sweep chart
  const cw = 520, ch = 190, m = { l: 40, r: 12, t: 14, b: 34 };
  const iw = cw - m.l - m.r, ih = ch - m.t - m.b;
  const ymin = 0.5, ymax = 0.72;
  const sx = (i) => m.l + (positions.length > 1 ? (i / (positions.length - 1)) * iw : 0);
  const sy = (v) => m.t + ih - ((v - ymin) / (ymax - ymin)) * ih;
  const pts = positions.map((p, i) => ({ i, p, v: sweep[keyOf(p)] ? sweep[keyOf(p)].ba : null })).filter((q) => q.v != null);
  return (
    <Panel n="3" title="Is the Dnipro a special divide?"
      lead="Move a straight line across the country and see how well subject headings separate the two sides. The Dnipro is drawn as a curve, with a 40 km band on each side left out. If the river were a unique boundary, it should beat the straight lines.">
      <div className="tl-toolbar">
        <label>Line <select value={mode} onChange={(e) => setMode(e.target.value)}><option value="dnipro">The Dnipro</option><option value="v">Split west / east (vertical line)</option><option value="h">Split north / south (horizontal line)</option></select></label>
        {mode !== 'dnipro' && (
          <label className="tl-grow">Position <input type="range" min="0" max={positions.length - 1} value={idx} onChange={(e) => setPos(positions[+e.target.value])} /> <b>{pos}°{mode === 'v' ? 'E' : 'N'}</b></label>
        )}
        <label>Evidence <select value={level} onChange={(e) => setLevel(e.target.value)}><option value="record">Books about one side</option><option value="place">Places</option></select></label>
      </div>
      <div className="tl-row">
        <div className="tl-col tl-map">
          <svg viewBox={`0 0 ${W} ${H}`} className="tl-svg">
            {gridLines()}
            <path d={outlinePath(data.outline)} className="tl-outline" />
            {mode === 'v' && <rect x={px(pos) - 40 * KM_PX * 0.67} y="0" width={80 * KM_PX * 0.67} height={H} fill={C.aqua} opacity="0.12" />}
            {mode === 'h' && <rect x="0" y={py(pos) - 40 * KM_PX} width={W} height={80 * KM_PX} fill={C.aqua} opacity="0.12" />}
            {mode === 'v' && <line x1={px(pos)} x2={px(pos)} y1="0" y2={H} stroke={C.aqua} strokeWidth="2" strokeDasharray="7 5" />}
            {mode === 'h' && <line x1="0" x2={W} y1={py(pos)} y2={py(pos)} stroke={C.aqua} strokeWidth="2" strokeDasharray="7 5" />}
            <polyline points={river} fill="none" stroke={mode === 'dnipro' ? C.white : '#7d8794'} strokeWidth={mode === 'dnipro' ? 3 : 1.6} />
            {D.points.map((p, i) => (
              <circle key={i} cx={px(p[2])} cy={py(p[1])} r={2.4 + Math.sqrt(p[3]) * 0.3}
                fill={sides[i] === 1 ? C.orange : sides[i] === -1 ? C.blue : C.grey} opacity={sides[i] === 0 ? 0.35 : 0.9} />
            ))}
          </svg>
          <div className="tl-legend"><span><i style={{ background: C.orange }} />{names[0]} ({nA})</span><span><i style={{ background: C.blue }} />{names[1]} ({nB})</span><span><i style={{ background: C.grey }} />left out</span></div>
        </div>
        <div className="tl-col">
          <svg viewBox={`0 0 ${cw} ${ch}`} className="tl-hist">
            {[0.5, 0.6, 0.7].map((v) => <g key={v}><line x1={m.l} x2={cw - m.r} y1={sy(v)} y2={sy(v)} className="tl-grid" /><text x={m.l - 5} y={sy(v) + 4} textAnchor="end" className="tl-tick">{v.toFixed(1)}</text></g>)}
            <line x1={m.l} x2={cw - m.r} y1={sy(dn)} y2={sy(dn)} stroke={C.white} strokeDasharray="5 4" />
            <text x={m.l + 6} y={sy(dn) + 15} textAnchor="start" className="tl-marklabel" fill={C.white}>Dnipro {fmt(dn)}</text>
            {mode !== 'dnipro' && <polyline points={pts.map((q) => `${sx(q.i)},${sy(q.v)}`).join(' ')} fill="none" stroke={C.grey} strokeWidth="2" />}
            {mode !== 'dnipro' && pts.map((q) => <circle key={q.i} cx={sx(q.i)} cy={sy(q.v)} r={q.p === pos ? 6 : 3} fill={q.p === pos ? C.aqua : C.grey} />)}
            {positions.map((p, i) => (i % 2 === 0 ? <text key={p} x={sx(i)} y={ch - 14} textAnchor="middle" className="tl-tick">{p}</text> : null))}
            <text x={m.l + iw / 2} y={ch - 1} textAnchor="middle" className="tl-axis">{mode === 'v' ? 'line position, °E' : mode === 'h' ? 'line position, °N' : ''}</text>
          </svg>
          <div className="tl-readout">
            <p>{mode === 'dnipro' ? 'The Dnipro' : `The ${pos}°${mode === 'v' ? 'E' : 'N'} line`} separates the two sides with a balanced accuracy of <b>{fmt(cur ? cur.ba : null)}</b>{cur ? <> on {cur.n} {level === 'record' ? 'books' : 'places'}</> : ''}. Guessing scores 0.50.</p>
            <p className="tl-muted">{cur && cur.ba != null && mode !== 'dnipro' ? (cur.ba > dn ? 'This line separates subject headings better than the Dnipro does.' : 'The Dnipro separates subject headings at least as well as this line.') : ''} Across all lines the scores sit between 0.59 and 0.68, so subject headings change gradually across the country and the river is not a special break. Lines near the Black Sea coast and the far west do slightly better than the river.</p>
          </div>
        </div>
      </div>
    </Panel>
  );
}

// ---------- 4 · period against region ----------------------------------------------
function PeriodRegion({ data }) {
  const [spec, setSpec] = useState('widened');
  const [res, setRes] = useState({ era: [], reg: [] });
  const [running, setRunning] = useState(false);
  const anim = useAnimator();
  const s = data.period_region[spec];
  const rows = useMemo(() => buildRows(s), [s]);
  const obs = useMemo(() => ({
    era: betweenShare(rows, s.V, rows.map((r) => [r.era]), s.eras.length),
    reg: betweenShare(rows, s.V, rows.map((r) => r.regs), s.regions.length),
  }), [rows, s]);
  useEffect(() => { anim.stop(); setRunning(false); setRes({ era: [], reg: [] }); }, [spec]); // eslint-disable-line
  const go = (total) => {
    setRunning(true);
    let done = 0;
    anim.loop(() => {
      const e2 = [], r2 = [];
      for (let i = 0; i < 4 && done < total; i++, done++) {
        const eras = shuffled(rows.map((r) => r.era));
        e2.push(betweenShare(rows, s.V, eras.map((x) => [x]), s.eras.length));
        const regs = shuffled(rows.map((r) => r.regs));
        r2.push(betweenShare(rows, s.V, regs, s.regions.length));
      }
      setRes((cur) => ({ era: cur.era.concat(e2), reg: cur.reg.concat(r2) }));
      return done < total;
    }, () => setRunning(false));
  };
  const n = res.era.length;
  const maxv = Math.max(obs.era, obs.reg, ...res.era, ...res.reg, 0.09) * 1.15;
  const pe = (res.era.filter((v) => v >= obs.era).length + 1) / (n + 1);
  const pr = (res.reg.filter((v) => v >= obs.reg).length + 1) / (n + 1);
  const mean = (a) => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : NaN);
  return (
    <Panel n="4" title="Does period or region explain subject headings better?"
      lead="Each book is described by its subject terms. We measure how much of the difference between books is explained by their period, and by their region, then shuffle the labels many times to see what each would explain by chance.">
      <div className="tl-toolbar">
        <label className="tl-grow">Records <select value={spec} onChange={(e) => setSpec(e.target.value)}>
          <option value="baseline">{data.period_region.baseline.rows.length} records: dated from headings, one region each</option>
          <option value="widened">{data.period_region.widened.rows.length} records: dated from "about" years, fractional regions</option>
        </select></label>
        <div className="tl-btns">
          <button onClick={() => go(40)} disabled={running}>Shuffle 40</button>
          <button onClick={() => go(300)} disabled={running}>Shuffle 300</button>
          <button className="tl-ghost" onClick={() => { anim.stop(); setRunning(false); setRes({ era: [], reg: [] }); }}>Reset</button>
        </div>
      </div>
      <div className="tl-row">
        <div className="tl-col">
          <h3>Period</h3>
          <Hist values={res.era} xmin={0} xmax={maxv} bins={36} height={170} xlabel="share of topic variance explained"
            marks={[{ x: obs.era, color: C.blue, label: `real ${pct(obs.era)}` }]} />
        </div>
        <div className="tl-col">
          <h3>Region</h3>
          <Hist values={res.reg} xmin={0} xmax={maxv} bins={36} height={170} xlabel="share of topic variance explained"
            marks={[{ x: obs.reg, color: C.orange, label: `real ${pct(obs.reg)}` }]} />
        </div>
      </div>
      <div className="tl-readout">
        <p>Period explains <b>{pct(obs.era)}</b> of the variance in subject headings and region explains <b>{pct(obs.reg)}</b>, a ratio of <b>{(obs.era / obs.reg).toFixed(2)}</b>. {n > 0 ? <>After {n} shuffles, chance gives about {pct(mean(res.era))} for period and {pct(mean(res.reg))} for region; p ≈ {fmt(pe)} and {fmt(pr)}.</> : 'Press a shuffle button to see what chance gives.'}</p>
        <p className="tl-muted">Both effects are above chance. Period explains about twice as much as region, so subject headings follow a shared chronology more than geography, and regions are still not interchangeable. This is the least certain result in the paper: it uses only records that name a located place in one of the four regions.</p>
      </div>
    </Panel>
  );
}

// ---------- 5 · which way do the ovals lean? ------------------------------------------
const DEF = { x: -130, y: -190, w: 962 };
const CITIES = { Moscow: [55.75, 37.62], Warsaw: [52.23, 21.01], Berlin: [52.52, 13.41], Vienna: [48.21, 16.37], Budapest: [47.5, 19.04], Bucharest: [44.43, 26.1], Istanbul: [41.01, 28.98], Minsk: [53.9, 27.57] };
const bearingTo = (la1, lo1, la2, lo2) => {
  const p = Math.PI / 180, y = Math.sin((lo2 - lo1) * p) * Math.cos(la2 * p);
  const x = Math.cos(la1 * p) * Math.sin(la2 * p) - Math.sin(la1 * p) * Math.cos(la2 * p) * Math.cos((lo2 - lo1) * p);
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
};
const axisDiff = (a, b) => { const d = Math.abs(a - b) % 180; return Math.min(d, 180 - d); };
function Lean({ data }) {
  const kind = KIND;
  const [level, setLevel] = useState(1);
  const [tA, setTA] = useState('Moscow');
  const [tB, setTB] = useState('Warsaw');
  const [tol, setTol] = useState(22.5);
  const [minEl, setMinEl] = useState(1.5);
  const [sel, setSel] = useState(null);
  const [view, setView] = useState(DEF);
  const svgRef = useRef(null);
  const drag = useRef(null);
  const clampView = (v) => { const w = Math.min(1100, Math.max(W / 40, v.w)), h = (w * H) / W; return { w, x: Math.min(W + 250 - w, Math.max(-250, v.x)), y: Math.min(H + 150 - h, Math.max(-300, v.y)) }; };
  const zoomAt = (f, fx = 0.5, fy = 0.5) => setView((v) => { const w = Math.min(1100, Math.max(W / 40, v.w * f)), h = (w * H) / W, vh = (v.w * H) / W; return clampView({ w, x: v.x + (v.w - w) * fx, y: v.y + (vh - h) * fy }); });
  const onWheel = (e) => { const r = svgRef.current.getBoundingClientRect(); zoomAt(e.deltaY < 0 ? 0.8 : 1.25, (e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height); };
  const onDown = (e) => { drag.current = { x: e.clientX, y: e.clientY, v: view, moved: false }; };
  const onMove = (e) => { const d = drag.current; if (!d) return; const r = svgRef.current.getBoundingClientRect(); const dx = e.clientX - d.x, dy = e.clientY - d.y; if (Math.abs(dx) + Math.abs(dy) > 3) d.moved = true; if (d.moved) setView(clampView({ w: d.v.w, x: d.v.x - (dx / r.width) * d.v.w, y: d.v.y - (dy / r.height) * ((d.v.w * H) / W) })); };
  const onUp = () => { drag.current = null; };
  const set = data.compact[kind];
  const poolAll = useMemo(() => set.pool.filter((p) => keepRow(p[4], level)), [set, level]);
  const rows = useMemo(() => {
    const pool = set.pts.filter((p) => keepRow(p[4], level));
    const by = {};
    for (const p of pool) (by[p[3]] = by[p[3]] || []).push(p);
    const out = [];
    for (const c of set.clusters) {
      const m = by[c.id];
      if (!m || m.length < 6) continue;
      const s = spread(m.map((p) => p[0]), m.map((p) => p[1]), m.map((p) => p[2]));
      if (!s) continue;
      out.push({ id: c.id, label: c.label, books: c.n, n: m.length, pts: m, lat: s.latC, lon: s.lonC, elong: s.elong, ra: s.ra, rb: s.rb, lean: (((90 - s.theta) % 180) + 180) % 180 });
    }
    return out;
  }, [set, level]);
  const el = useMemo(() => rows.filter((r) => r.elong >= minEl), [rows, minEl]);
  const classify = (r, lean) => {
    const da = axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES[tA])), db = axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES[tB]));
    if (Math.min(da, db) > tol) return 'neither';
    return da <= db ? tA : tB;
  };
  const obs = useMemo(() => { const c = { [tA]: 0, [tB]: 0, neither: 0 }; el.forEach((r) => { c[classify(r, r.lean)] += 1; }); return c; }, [el, tA, tB, tol]); // eslint-disable-line
  useEffect(() => { setSel(null); setView(DEF); }, [level]);
  useEffect(() => {
    const r = rows.find((q) => q.id === sel);
    if (!r) { setView(DEF); return; }
    const reach = Math.max(r.ra * KM_PX * 1.5, 60), w = Math.min(W, Math.max(W / 12, reach * 2 * 1.2));
    setView(clampView({ w, x: px(r.lon) - w / 2, y: py(r.lat) - (w * H) / W / 2 }));
  }, [sel]); // eslint-disable-line
  // fair null, as in the paper: random sets of places of the same sizes (not random bearings, which are too easy to beat
  // because Ukraine is wider from east to west than from north to south). Draws are made once per place set and cached.
  const [draws, setDraws] = useState(null);
  useEffect(() => {
    let off = false; const N = 300, out = []; setDraws(null);
    const step = () => {
      if (off) return;
      for (let i = 0; i < 10 && out.length < N; i++) {
        out.push(rows.map((r) => {
          const ix = sampleIdx(poolAll.length, r.n), q = ix.map((j) => poolAll[j]);
          const sp = spread(q.map((p) => p[0]), q.map((p) => p[1]), q.map((p) => p[2]));
          return sp ? { lat: sp.latC, lon: sp.lonC, elong: sp.elong, lean: (((90 - sp.theta) % 180) + 180) % 180 } : null;
        }));
      }
      setDraws({ n: out.length, list: out.slice() });
      if (out.length < N) setTimeout(step, 0);
    };
    setTimeout(step, 0);
    return () => { off = true; };
  }, [rows, poolAll]); // eslint-disable-line
  const sims = useMemo(() => {
    if (!draws || draws.n < 20) return null;
    const arrA = [], arrB = [];
    for (const d of draws.list) {
      let a = 0, b = 0;
      d.forEach((q) => { if (!q || q.elong < minEl) return; const t = classify(q, q.lean); if (t === tA) a++; else if (t === tB) b++; });
      arrA.push(a); arrB.push(b);
    }
    return { arrA, arrB, n: draws.n };
  }, [draws, tA, tB, tol, minEl]); // eslint-disable-line
  const mean = (a) => a.reduce((x, y) => x + y, 0) / (a.length || 1);
  const pGE = (a, v) => (a.filter((x) => x >= v).length + 1) / (a.length + 1);
  const names = Object.keys(CITIES);
  const compass = (b) => ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'][Math.round(((b % 360) / 45)) % 8];
  return (
    <Panel n="5" title="Which way do the ovals lean?"
      lead="Each oval has a long axis. Here we ask whether the long axes of the subject headings lean towards Moscow or towards the West more often than the ovals of random sets of places of the same sizes would. An axis has two ends, so it can line up with a city at either end. Moscow and Istanbul lie in similar directions seen from Ukraine, so an oval can fall within the window of both; choose Moscow with Istanbul below to assign each oval to the nearer axis. In the paper this head-to-head gives 23 ovals towards Moscow (12.7 expected) and 4 towards Istanbul (5.9 expected).">
      <div className="tl-toolbar">
        <label>Places <select value={level} onChange={(e) => setLevel(+e.target.value)}>{[1, 2].map((i) => <option key={i} value={i}>{LEVEL_LABEL[i]}</option>)}</select></label>
        <label>Compare <select value={tA} onChange={(e) => setTA(e.target.value)}>{names.filter((n) => n !== tB).map((n) => <option key={n}>{n}</option>)}</select>
          {' with '}<select value={tB} onChange={(e) => setTB(e.target.value)}>{names.filter((n) => n !== tA).map((n) => <option key={n}>{n}</option>)}</select></label>
        <label>Tolerance ±{tol}° <input type="range" min="10" max="45" step="2.5" value={tol} onChange={(e) => setTol(+e.target.value)} /></label>
        <label>Only ovals at least {minEl.toFixed(1)}× as long as wide <input type="range" min="1" max="3" step="0.1" value={minEl} onChange={(e) => setMinEl(+e.target.value)} /></label>
      </div>
      <div className="tl-row">
        <div className="tl-map">
          <div className="tl-zoombtns"><button onClick={() => zoomAt(0.7)} aria-label="Zoom in">+</button><button onClick={() => zoomAt(1.4)} aria-label="Zoom out">−</button><button onClick={() => { setSel(null); setView(DEF); }}>Reset</button><span className="tl-muted">scroll to zoom, drag to move</span></div>
          <svg ref={svgRef} viewBox={`${view.x} ${view.y} ${view.w} ${(view.w * H) / W}`} className="tl-svg" style={{ touchAction: 'none', cursor: drag.current && drag.current.moved ? 'grabbing' : 'grab' }}
            onWheel={onWheel} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerLeave={onUp}>
            {gridLines()}
            <path d={outlinePath(data.outline)} className="tl-outline" />
            {rows.filter((r) => sel === null || r.id === sel).map((r) => {
              const on = r.elong >= minEl, t = on ? classify(r, r.lean) : 'off';
              const col = t === tA ? C.orange : t === tB ? C.blue : C.pale;
              const cx = px(r.lon), cy = py(r.lat), isSel = sel === r.id;
              const th = ((90 - r.lean) * Math.PI) / 180;
              const ex = Math.cos(th) * r.ra * KM_PX, ey = -Math.sin(th) * r.ra * KM_PX;
              return (
                <g key={r.id} onClick={() => setSel(isSel ? null : r.id)} style={{ cursor: 'pointer' }}>
                  <ellipse cx={cx} cy={cy} rx={r.ra * KM_PX} ry={r.rb * KM_PX} transform={`rotate(${-(90 - r.lean)} ${cx} ${cy})`}
                    fill={col} fillOpacity={isSel ? 0.3 : 0.07} stroke={col} strokeWidth={(isSel ? 3 : 1.4) * (view.w / W)} strokeOpacity={on || isSel ? 0.95 : 0.35} strokeDasharray={on ? undefined : '4 4'} />
                  {isSel && <><line x1={cx - ex} y1={cy - ey} x2={cx + ex} y2={cy + ey} stroke="#fff" strokeWidth={2 * (view.w / W)} /><circle cx={cx} cy={cy} r={3.5 * (view.w / W)} fill="#fff" />{r.pts.map((p, i) => <circle key={i} cx={px(p[1])} cy={py(p[0])} r={Math.min(6, 2 + Math.sqrt(p[2]) * 0.35) * (view.w / W)} fill={col} fillOpacity="0.7" stroke="#000" strokeWidth={0.5 * (view.w / W)} />)}</>}
                </g>
              );
            })}
            {[tA, tB].map((nm, i) => {
              const col = i === 0 ? C.orange : C.blue, [cl, co] = CITIES[nm];
              const x0 = px(30.52), y0 = py(50.45), x1 = px(co), y1 = py(cl);
              const dim = sel !== null;
              return (<g key={nm} opacity={dim ? 0.5 : 1}><line x1={x0} y1={y0} x2={x1} y2={y1} stroke={col} strokeWidth={2 * (view.w / W)} strokeDasharray="3 5" /><circle cx={x1} cy={y1} r={5 * (view.w / W)} fill={col} /><text x={x1 + 8 * (view.w / W)} y={y1 + 4 * (view.w / W)} fill={col} style={{ fontSize: 13 * (view.w / W) }} className="tl-marklabel">{nm} ({Math.round(bearingTo(50.45, 30.52, cl, co))}° from Kyiv)</text></g>);
            })}
          </svg>
          <div className="tl-legend"><span><i style={{ background: C.orange }} />leans towards {tA}</span><span><i style={{ background: C.blue }} />leans towards {tB}</span><span><i style={{ background: C.pale }} />neither, or not elongated enough (dashed)</span></div>
          <p className="tl-note">Each oval is drawn at its subject heading's centre with its real radii and lean. Click an oval or a table row to show only that heading, with its places and long axis, and zoom to it. Click again, or press Reset, to return. The dotted lines run from Kyiv to the two cities, so you can see the directions the long axes are compared with. Each oval's lean is measured from its own centre.</p>
        </div>
        <div className="tl-col">
      <div className="tl-readout">
        <p><b>{el.length}</b> of {rows.length} subject headings have an oval that is at least {minEl.toFixed(1)} times as long as wide. Counted as leaning towards {tA}, towards {tB}, or neither, within ±{tol}°:</p>
        {sims && (
          <table className="tl-table">
            <thead><tr><th></th><th>Observed</th><th>Expected by chance</th><th>p (as many or more)</th></tr></thead>
            <tbody>
              <tr><td>towards {tA}</td><td><b>{obs[tA]}</b></td><td>{mean(sims.arrA).toFixed(1)}</td><td>{pGE(sims.arrA, obs[tA]).toFixed(3)}</td></tr>
              <tr><td>towards {tB}</td><td><b>{obs[tB]}</b></td><td>{mean(sims.arrB).toFixed(1)}</td><td>{pGE(sims.arrB, obs[tB]).toFixed(3)}</td></tr>
              <tr><td>neither</td><td>{obs.neither}</td><td>{(el.length - mean(sims.arrA) - mean(sims.arrB)).toFixed(1)}</td><td></td></tr>
            </tbody>
          </table>
        )}
        {sims && <Hist values={sims.arrA} xmin={0} xmax={Math.max(el.length, 1)} bins={Math.min(32, Math.max(el.length, 2))} height={170} xlabel={`number of ovals leaning towards ${tA} in ${sims.n} random sets of places`}
          marks={[{ x: obs[tA], color: C.blue, label: `observed ${obs[tA]}` }]} />}
      </div>
      <div className="tl-tablewrap">
        <table className="tl-table">
          <thead><tr><th>Subject heading</th><th>Books</th><th>Places</th><th>Lean (° from north)</th><th>Long ÷ short</th><th>Off {tA} axis</th><th>Off {tB} axis</th></tr></thead>
          <tbody>
            {rows.slice().sort((a, b) => b.elong - a.elong).map((r) => (
              <tr key={r.id} onClick={() => setSel(sel === r.id ? null : r.id)} style={{ opacity: r.elong >= minEl ? 1 : 0.45, cursor: 'pointer', background: sel === r.id ? '#1f2a38' : undefined }}>
                <td>{r.label}</td><td>{r.books}</td><td>{r.n}</td><td>{Math.round(r.lean)}° ({compass(r.lean)}–{compass(r.lean + 180)})</td><td>{r.elong.toFixed(1)}</td>
                <td>{Math.round(axisDiff(r.lean, bearingTo(r.lat, r.lon, ...CITIES[tA])))}°</td><td>{Math.round(axisDiff(r.lean, bearingTo(r.lat, r.lon, ...CITIES[tB])))}°</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
        </div>
      </div>
      <p className="tl-note">Direction is measured from each heading's own centre, and the comparison is with random sets of places of the same sizes. Adding more cities makes almost every oval line up with one of them, because the cities surround Ukraine, so compare two at a time. With Moscow and Warsaw, more headings lean towards Moscow than chance gives, but they are the ones that name Russia, the Soviet Union or Crimea among their places (politics and government, relations, autonomy and independence movements and so on); the Warsaw count is what chance gives. In the paper, with 1,000 random sets per theme, 26 of 64 elongated themes lean towards Moscow against about 16 expected; here the number of draws is smaller, so the expected count is a little less steady.</p>
    </Panel>
  );
}

// ---------- page ----------------------------------------------------------------------
export default function TestsLab() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/tests_lab.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    return () => { off = true; };
  }, []);
  return (
    <div className="tl-root">
      <p className="tl-back"><Link to="/place-map">← Topical map of Ukraine</Link> · <Link to="/drift-lab">Drift lab: is the country pulling apart? →</Link> · <Link to="/catalog-lab">Catalog lab →</Link></p>
      <h1>Tests lab: try the tests from the paper</h1>
      <p className="tl-sub">The paper asks whether the literature on Ukraine in the DK508 catalog splits into regions. Each panel below runs one of its tests on the real data. Everything here is computed in your browser, except the classifier, whose shuffled scores were computed beforehand. Random draws change every time, so a p-value will move a little between runs.</p>
      {error && <p className="tl-err">The data file could not be loaded.</p>}
      {!data && !error && <p className="tl-muted">Loading…</p>}
      {data && (<><Compactness data={data} /><Classifier data={data} /><Dnipro data={data} /><PeriodRegion data={data} /><Lean data={data} /></>)}
    </div>
  );
}
