import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as d3 from 'd3';
import { Link } from 'react-router-dom';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import 'leaflet.heat';
import './PlaceClusters.css';

// Topical map of "aboutness": UMAP of subject places (optionally split by period) or of books,
// clusters from HDBSCAN, cluster-defining features from XGBoost + SHAP.
// Data: public/data/place_clusters.json (scripts/place_clusters.py).

const KINDS = [
  ['place_period', 'Place clusters · by period', 'Each point is a place in one period (e.g. Crimea 1991–2013). Shows how topics change with time as well as place.'],
  ['place', 'Place clusters · all periods', 'Each point is a place, described by everything written about it across all periods.'],
  ['record', 'Document (book) clusters', 'Each point is one book, described by its topics, periods and languages. The finest view; the clearest topical themes.'],
];
const GREY = '#5b6068';
const colorOfCluster = (c) => (c < 0 ? GREY : d3.hsl((c * 137.508) % 360, 0.62, 0.62).formatRgb());
const eraColor = (i, n) => d3.interpolateTurbo(0.08 + 0.84 * (i / Math.max(1, n - 1)));
const pretty = (f) => f.replace(/^(topic|heading|period|language): /, (m, k) => k[0].toUpperCase() + k.slice(1) + ': ');
const pct = (v) => `${Math.round(v * 100)}%`;


// Geographic view: the same clusters, drawn where the subject places are.
function GeoMap({ set, kind, sel, needle, colorOf, onPick, mode, eras, showEll, showTrack, showAllEll }) {
  const heat = useRef(null);
  const pc_fit = useRef(null);
  const el = useRef(null), map = useRef(null), layer = useRef(null);
  useEffect(() => {
    map.current = L.map(el.current, { worldCopyJump: true, zoomSnap: 0.25 });
    // start wide enough to show Warsaw and Moscow as well as Ukraine
    map.current.fitBounds([[43.5, 19.5], [57, 40.5]], { padding: [20, 20] });
    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}', {
      attribution: 'Esri, HERE, Garmin, FAO, NOAA, USGS &copy; OpenStreetMap contributors', maxZoom: 16 }).addTo(map.current);
    layer.current = L.layerGroup().addTo(map.current);
    // the two reference cities, always visible
    [['Moscow', 55.75, 37.62], ['Warsaw', 52.23, 21.01]].forEach(([nm, la, lo]) => {
      L.circleMarker([la, lo], { radius: 5, color: '#ffd166', weight: 2, fillColor: '#ffd166', fillOpacity: 1, interactive: false }).addTo(map.current);
      L.marker([la, lo], { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span style="color:#ffd166">${nm}</span>`, iconSize: [70, 14], iconAnchor: [-8, 7] }) }).addTo(map.current);
    });
    return () => { map.current.remove(); };
  }, []);
  useEffect(() => {
    const g = layer.current; g.clearLayers();
    if (sel === null) pc_fit.current = null;
    if (heat.current) { map.current.removeLayer(heat.current); heat.current = null; }
    let items;
    if (kind === 'record') {
      // books: one bubble per (cluster, place), sized by number of books in that cluster about that place
      items = (set.geo || []).map(([c, lat, lon, name, n]) => ({ c, lat, lon, name, n, sub: `${n} books in this cluster` }));
    } else {
      // places: points that share a location are spread on a small ring so overlapping clusters stay visible
      const by = {};
      set.points.forEach((p) => { (by[`${p.lat},${p.lon}`] = by[`${p.lat},${p.lon}`] || []).push(p); });
      items = [];
      Object.values(by).forEach((arr) => arr.forEach((p, i) => {
        const a = (i / arr.length) * 6.2832, r = arr.length > 1 ? 0.06 + 0.02 * arr.length : 0;
        items.push({ c: p.c, lat: p.lat + r * Math.sin(a), lon: p.lon + r * Math.cos(a) * 1.5, name: p.g, n: p.n, sub: `${p.n} books` });
      }));
    }
    if (showEll && set.overall && set.overall.ellipse) {
      // reference oval for ALL places / books (prominent when no topic is selected, faint reference otherwise)
      const E = set.overall.ellipse, all = sel === null, col = '#e8e8e8';
      L.polygon(E.poly, { color: col, weight: all ? 3 : 1.5, dashArray: '8 6', fillColor: col, fillOpacity: all ? 0.07 : 0.02, opacity: all ? 0.95 : 0.45, interactive: all })
        .bindTooltip(`<b>${kind === 'record' ? 'All books' : 'All places'}</b><br>${set.overall.caption}`, { sticky: true, maxWidth: 320 }).addTo(g);
      if (all && !showAllEll) {
        const tipA = (km, bear) => { const r = bear * Math.PI / 180; return [E.lat + (km * Math.cos(r)) / 110.57, E.lon + (km * Math.sin(r)) / (111.32 * Math.cos(E.lat * Math.PI / 180))]; };
        [[E.a_km, E.bearing, 'long axis', null], [E.a_km, E.bearing + 180, 'long axis', null], [E.b_km, E.bearing + 90, 'short axis', '6 5'], [E.b_km, E.bearing + 270, 'short axis', '6 5']].forEach(([km, br, nm, dash]) => {
          const t = tipA(km, br);
          L.polyline([[E.lat, E.lon], t], { color: col, weight: 2, opacity: 0.9, dashArray: dash }).bindTooltip(`${nm}: radius ${km} km from the centre to the edge (1 SD); the axis runs both ways`).addTo(g);
          L.marker(t, { interactive: false, icon: L.divIcon({ className: 'pc-arrow', html: `<span style="transform:rotate(${br - 90}deg);color:${col}">➤</span>`, iconSize: [14, 14], iconAnchor: [7, 7] }) }).addTo(g);
        });
        L.circleMarker([E.lat, E.lon], { radius: 4, color: '#fff', weight: 1, fillColor: '#999', fillOpacity: 1, interactive: false }).addTo(g);
        L.marker(tipA(E.a_km, E.bearing), { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span>all ${kind === 'record' ? 'books' : 'places'}: ${E.a_km} km</span>`, iconSize: [120, 14], iconAnchor: [-6, 7] }) }).addTo(g);
        L.marker(tipA(E.b_km, E.bearing + 90), { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span>${E.b_km} km</span>`, iconSize: [60, 14], iconAnchor: [-6, 7] }) }).addTo(g);
      }
    }
    if (sel !== null || showAllEll) {
      set.clusters.forEach((cl) => {
        if (cl.id < 0) return;
        const mine = sel === cl.id;
        if (!mine && !showAllEll) return;
        if (showEll && cl.ellipse) {
          const col = colorOf(cl.id);
          L.polygon(cl.ellipse.poly, { color: col, weight: mine ? 3 : 1.5, fillColor: col, fillOpacity: mine ? 0.18 : 0.04, opacity: mine || sel === null ? 0.95 : 0.55, dashArray: cl.ellipse.places < 5 ? '4 4' : null, interactive: true })
            .bindTooltip(`<b>${cl.label}</b><br>${cl.caption}`, { sticky: true, maxWidth: 320 }).on('click', () => onPick(cl.id)).addTo(g);
          L.circleMarker([cl.ellipse.lat, cl.ellipse.lon], { radius: 3, color: '#fff', weight: 1, fillColor: col, fillOpacity: 1, interactive: false }).addTo(g);
          if (mine && (!pc_fit.current || pc_fit.current !== sel)) { pc_fit.current = sel; map.current.fitBounds(L.polygon(cl.ellipse.poly).getBounds().pad(0.6), { maxZoom: 9 }); }
          if (!mine) { /* no axes for the others */ } else {
          // axes from the centre: long axis (solid, both directions) and short axis (dashed) with arrowheads
          const E = cl.ellipse, la = E.lat, lo = E.lon;
          const tip = (km, bear) => { const r = bear * Math.PI / 180; return [la + (km * Math.cos(r)) / 110.57, lo + (km * Math.sin(r)) / (111.32 * Math.cos(la * Math.PI / 180))]; };
          [[E.a_km, E.bearing, 'long axis', null], [E.a_km, E.bearing + 180, 'long axis', null], [E.b_km, E.bearing + 90, 'short axis', '6 5'], [E.b_km, E.bearing + 270, 'short axis', '6 5']].forEach(([km, br, nm, dash]) => {
            const t = tip(km, br);
            L.polyline([[la, lo], t], { color: '#fff', weight: nm === 'long axis' ? 2.5 : 1.8, opacity: 0.95, dashArray: dash }).bindTooltip(`${nm}: radius ${km} km from the centre to the edge (1 SD); the axis runs both ways`).addTo(g);
            L.marker(t, { interactive: false, icon: L.divIcon({ className: 'pc-arrow', html: `<span style="transform:rotate(${br - 90}deg);color:#fff">➤</span>`, iconSize: [14, 14], iconAnchor: [7, 7] }) }).addTo(g);
          });
          L.marker(tip(E.a_km, E.bearing), { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span>radius ${E.a_km} km · leans ${E.bearing}°</span>`, iconSize: [170, 14], iconAnchor: [-6, 7] }) }).addTo(g);
          L.marker(tip(E.b_km, E.bearing + 90), { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span>radius ${E.b_km} km</span>`, iconSize: [90, 14], iconAnchor: [-6, 7] }) }).addTo(g);
          // reference directions from the cluster's centre: towards Moscow and towards Warsaw (short pointers, so they stay in view)
          [['Moscow', 55.75, 37.62], ['Warsaw', 52.23, 21.01]].forEach(([nm, rla, rlo]) => {
            const p1 = la * Math.PI / 180, p2 = rla * Math.PI / 180, dl = (rlo - lo) * Math.PI / 180;
            const bg = (Math.atan2(Math.sin(dl) * Math.cos(p2), Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dl)) * 180 / Math.PI + 360) % 360;
            const t = tip(Math.max(E.a_km, E.b_km) * 1.35, bg);
            L.polyline([[la, lo], t], { color: '#ffd166', weight: 2, opacity: 0.95, dashArray: '2 6', interactive: false }).addTo(g);
            L.marker(t, { interactive: false, icon: L.divIcon({ className: 'pc-arrow', html: `<span style="transform:rotate(${bg - 90}deg);color:#ffd166">➤</span>`, iconSize: [14, 14], iconAnchor: [7, 7] }) }).addTo(g);
            L.marker(t, { interactive: false, icon: L.divIcon({ className: 'pc-axislabel', html: `<span style="color:#ffd166">towards ${nm} ${Math.round(bg)}°</span>`, iconSize: [150, 14], iconAnchor: [-8, 7] }) }).addTo(g);
          });
          }
        }
        if (showTrack && cl.track && (sel === null || mine)) {
          const col = colorOf(cl.id), tr = cl.track;
          L.polyline(tr.map((t) => [t.lat, t.lon]), { color: col, weight: mine ? 3 : 2, opacity: 0.9, dashArray: '2 5' }).addTo(g);
          tr.forEach((t, i) => {
            L.circleMarker([t.lat, t.lon], { radius: 3 + i * 0.4, color: '#000', weight: 1, fillColor: col, fillOpacity: 1 })
              .bindTooltip(`${eras[t.e]}${t.km ? ` · moved ${t.km} km ${t.dir}` : ''} (${t.n} books)`).addTo(g);
            if (i > 0) {
              const p = tr[i - 1], ang = Math.atan2((t.lat - p.lat) * 1, (t.lon - p.lon) * Math.cos(t.lat * Math.PI / 180)) * 180 / Math.PI;
              L.marker([(t.lat + p.lat) / 2, (t.lon + p.lon) / 2], { interactive: false, icon: L.divIcon({ className: 'pc-arrow', html: `<span style="transform:rotate(${90 - ang}deg);color:${col}">➤</span>`, iconSize: [14, 14] }) }).addTo(g);
            }
          });
        }
      });
    }
    if (mode === 'heat') {
      const pts = items.filter((it) => (sel === null || it.c === sel) && (!needle || it.name.toLowerCase().includes(needle))).map((it) => [it.lat, it.lon, Math.min(1, it.n / 8 + 0.15)]);
      heat.current = L.heatLayer(pts, { radius: 26, blur: 22, maxZoom: 9, minOpacity: 0.3 }).addTo(map.current);
      return;
    }
    const rs = d3.scaleSqrt().domain([1, d3.max(items, (i) => i.n) || 1]).range([3, 17]);
    items.sort((a, b) => ((a.c === sel) - (b.c === sel)));
    items.forEach((it) => {
      const on = (sel === null || it.c === sel) && (!needle || it.name.toLowerCase().includes(needle));
      L.circleMarker([it.lat, it.lon], { radius: rs(it.n), color: '#000', weight: 0.5, fillColor: colorOf(it.c), fillOpacity: on ? 0.75 : 0.06, opacity: on ? 0.6 : 0.05 })
        .bindTooltip(`<b>${it.name}</b><br>${it.sub}<br>${it.c < 0 ? 'unclustered' : (set.clusters.find((c) => c.id === it.c) || {}).label}`)
        .on('click', () => onPick(it.c)).addTo(g);
    });
  }, [set, kind, sel, needle, colorOf, onPick, mode, showEll, showTrack, showAllEll, eras]);
  return <div ref={el} className="pc-geo" />;
}


// compass bearing between two points, and the angle between an (undirected) axis and a bearing
const pcBearing = (la1, lo1, la2, lo2) => { const p = Math.PI / 180, y = Math.sin((lo2 - lo1) * p) * Math.cos(la2 * p), x = Math.cos(la1 * p) * Math.sin(la2 * p) - Math.sin(la1 * p) * Math.cos(la2 * p) * Math.cos((lo2 - lo1) * p); return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360; };
const pcAxisDiff = (a, b) => { const d = Math.abs(a - b) % 180; return Math.min(d, 180 - d); };
const pcLeanText = (E) => {
  if (!E) return null;
  const m = pcAxisDiff(E.bearing, pcBearing(E.lat, E.lon, 55.75, 37.62)), w = pcAxisDiff(E.bearing, pcBearing(E.lat, E.lon, 52.23, 21.01));
  const near = Math.min(m, w) > 22.5 || E.elong < 1.5 ? 'It does not clearly lean towards either.' : m < w ? 'It leans towards the Moscow axis.' : 'It leans towards the Warsaw axis.';
  return `Long axis leans ${E.bearing}° from north (it has two ends, so it also points ${(E.bearing + 180) % 360}°). Angle to the Moscow axis ${Math.round(m)}°, to the Warsaw axis ${Math.round(w)}°. ${near}`;
};

export default function PlaceClusters() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [kind, setKind] = useState('place_period');
  const [colorBy, setColorBy] = useState('cluster');
  const [view, setView] = useState('topic');
  const [showEll, setShowEll] = useState(true);
  const [showTrack, setShowTrack] = useState(true);
  const [showAllEll, setShowAllEll] = useState(false);
  const [sel, setSel] = useState(null);
  const [q, setQ] = useState('');
  const [hover, setHover] = useState(null);
  const wrap = useRef(null);
  const cvs = useRef(null);
  const [size, setSize] = useState({ w: 760, h: 620 });
  const tf = useRef(d3.zoomIdentity);
  const quad = useRef(null);

  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/place_clusters.json`).then((r) => r.json())
      .then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    return () => { off = true; };
  }, []);

  useEffect(() => {
    if (!wrap.current) return undefined;
    const ro = new ResizeObserver(([e]) => setSize({ w: Math.floor(e.contentRect.width), h: Math.max(460, Math.min(700, Math.floor(e.contentRect.width * 0.82))) }));
    ro.observe(wrap.current);
    return () => ro.disconnect();
  }, [data]);

  const set = data && data.sets[kind];
  const eras = data ? data.eras : [];

  const scales = useMemo(() => {
    if (!set) return null;
    const xs = set.points.map((p) => p.x), ys = set.points.map((p) => p.y);
    const pad = 24;
    return {
      x: d3.scaleLinear().domain(d3.extent(xs)).range([pad, size.w - pad]),
      y: d3.scaleLinear().domain(d3.extent(ys)).range([size.h - pad, pad]),
    };
  }, [set, size]);

  const needle = q.trim().toLowerCase();
  const matches = (p) => !needle || p.g.toLowerCase().includes(needle);
  const rScale = useMemo(() => (set ? d3.scaleSqrt().domain([1, d3.max(set.points, (p) => p.n) || 1]).range(kind === 'record' ? [2.2, 4] : [3, 12]) : null), [set, kind]);

  const colorOfPoint = (p) => {
    if (colorBy === 'era' && p.e !== undefined) return eraColor(p.e, eras.length);
    if (colorBy === 'theme') return d3.schemeTableau10[(data.bands.indexOf(p.b) + 10) % 10] || GREY;
    return colorOfCluster(p.c);
  };

  useEffect(() => {
    if (!set || !scales) return;
    const c = cvs.current, dpr = window.devicePixelRatio || 1;
    c.width = size.w * dpr; c.height = size.h * dpr; c.style.width = `${size.w}px`; c.style.height = `${size.h}px`;
    const ctx = c.getContext('2d');
    const draw = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size.w, size.h);
      const t = tf.current;
      const order = set.points.map((p, i) => i).sort((a, b) => (set.points[a].c === sel ? 1 : 0) - (set.points[b].c === sel ? 1 : 0));
      for (const i of order) {
        const p = set.points[i];
        const on = (sel === null || p.c === sel) && matches(p);
        const x = t.applyX(scales.x(p.x)), y = t.applyY(scales.y(p.y));
        if (x < -10 || y < -10 || x > size.w + 10 || y > size.h + 10) continue;
        ctx.globalAlpha = on ? (kind === 'record' ? 0.7 : 0.85) : 0.08;
        ctx.fillStyle = colorOfPoint(p);
        ctx.beginPath(); ctx.arc(x, y, rScale(p.n) * Math.sqrt(t.k), 0, 6.2832); ctx.fill();
      }
      ctx.globalAlpha = 1;
      if (hover) {
        const p = hover.p, x = t.applyX(scales.x(p.x)), y = t.applyY(scales.y(p.y));
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(x, y, rScale(p.n) * Math.sqrt(t.k) + 2, 0, 6.2832); ctx.stroke();
      }
    };
    draw();
    quad.current = d3.quadtree().x((p) => scales.x(p.x)).y((p) => scales.y(p.y)).addAll(set.points);
    const zoom = d3.zoom().scaleExtent([1, 14]).on('zoom', (e) => { tf.current = e.transform; draw(); });
    d3.select(c).call(zoom).on('dblclick.zoom', null);
    d3.select(c).call(zoom.transform, tf.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [set, scales, size, sel, colorBy, needle, hover, kind]);

  const onMove = (e) => {
    if (!quad.current || !scales) return;
    const r = cvs.current.getBoundingClientRect(), t = tf.current;
    const mx = (e.clientX - r.left - t.x) / t.k, my = (e.clientY - r.top - t.y) / t.k;
    const p = quad.current.find(mx, my, 14 / t.k);
    setHover(p ? { p, x: e.clientX - r.left, y: e.clientY - r.top } : null);
  };

  if (error) return <div className="pc-root"><p>Could not load the data.</p></div>;
  if (!data) return <div className="pc-root"><p className="pc-muted">Loading…</p></div>;

  const clusters = set.clusters.slice().sort((a, b) => (a.id < 0) - (b.id < 0) || b.n - a.n);
  const cur = sel === null ? null : set.clusters.find((c) => c.id === sel);
  const note = KINDS.find((k) => k[0] === kind)[2];

  return (
    <div className="pc-root">
      <div className="pc-links">
        <a href="#/">← About this project</a>
        <a href="#/map">Map &amp; network explorer →</a>
        <a href="#/topics">Subject themes river →</a>
        <a href="#/lag">Publication delay →</a>
      </div>
      <h1>Topical map of aboutness</h1>
      <p className="pc-sub">
        Which places are written about in similar ways? Each point is described only by <b>what is written about it</b> —
        topic themes, subject headings, the periods covered and the languages — never by where it is, so neighbours on this map
        share <i>topics</i>, not geography. Colours are clusters found automatically; click one to see what defines it.
      </p>

      <div className="pc-toolbar">
        <span>Cluster:</span>
        {KINDS.map(([k, label]) => (
          <button key={k} className={'pc-pill' + (kind === k ? ' on' : '')} onClick={() => { setKind(k); setSel(null); setHover(null); tf.current = d3.zoomIdentity; }}>{label}</button>
        ))}
        <span className="pc-sep" />
        {[['topic', 'Topic map'], ['geo', 'Geographic map'], ['heat', 'Heat map']].map(([k, l]) => (
          <button key={k} className={'pc-pill' + (view === k ? ' on' : '')} onClick={() => setView(k)}>{l}</button>
        ))}
        {view !== 'topic' && (<>
          <label><input type="checkbox" checked={showEll} onChange={(e) => setShowEll(e.target.checked)} /> Oval &amp; axes of selected topic</label>
          <label><input type="checkbox" checked={showAllEll} onChange={(e) => setShowAllEll(e.target.checked)} /> Show all topic ovals together</label>
          {kind === 'place_period' && <label><input type="checkbox" checked={showTrack} onChange={(e) => setShowTrack(e.target.checked)} /> Shift over time</label>}
        </>)}
        {view === 'topic' && <label>Colour by
          <select value={colorBy} onChange={(e) => setColorBy(e.target.value)}>
            <option value="cluster">Cluster</option>
            {kind === 'place_period' && <option value="era">Period</option>}
            <option value="theme">Main topic theme</option>
          </select>
        </label>}
        <input className="pc-search" placeholder={kind === 'record' ? 'Find a book title…' : 'Find a place…'} value={q} onChange={(e) => setQ(e.target.value)} />
      </div>
      <div className="pc-note">{note} <span className="pc-muted">{set.points.length.toLocaleString()} points · {set.n_clusters} clusters · {set.unclustered} unclustered.</span></div>

      <div className="pc-main">
        <div className="pc-plot" ref={wrap}>
          {view !== 'topic' && <GeoMap mode={view} eras={eras} showEll={showEll} showTrack={showTrack} showAllEll={showAllEll} set={set} kind={kind} sel={sel} needle={needle} colorOf={colorOfCluster} onPick={(c) => setSel(c < 0 ? null : c)} />}
          <canvas style={{ display: view !== 'topic' ? 'none' : 'block' }} ref={cvs} onMouseMove={onMove} onMouseLeave={() => setHover(null)} onClick={() => { if (hover) setSel(hover.p.c < 0 ? null : hover.p.c); }} />
          {view === 'topic' && hover && (
            <div className="pc-tip" style={{ left: Math.min(hover.x + 14, size.w - 250), top: Math.max(hover.y - 8, 0) }}>
              <b>{hover.p.g}</b>{hover.p.e !== undefined && <span> · {eras[hover.p.e]}</span>}
              <div className="pc-muted">{kind === 'record' ? 'book' : `${hover.p.n} books`} · {hover.p.c < 0 ? 'unclustered' : `cluster ${hover.p.c}`}</div>
              {hover.p.b && <div>{hover.p.b}</div>}
              {hover.p.t && hover.p.t.length > 0 && <div className="pc-muted">{hover.p.t.join(' · ')}</div>}
            </div>
          )}
          <div className="pc-hint">{view === 'heat' ? 'density of subject places (of the selected cluster, if any); click a topic to see its oval' : view === 'geo' ? 'bubbles = subject places; size = number of books; click a topic in the list (or a bubble) to see its oval and axes' : 'scroll to zoom, drag to pan, click a point to select its cluster'}</div>
        </div>

        <aside className="pc-side">
          <div className="pc-clist">
            {clusters.map((c) => (
              <button key={c.id} className={'pc-citem' + (sel === c.id ? ' on' : '')} onClick={() => setSel(sel === c.id ? null : c.id)}>
                <span className="pc-dot" style={{ background: colorOfCluster(c.id) }} />
                <span className="pc-clabel">{c.label}</span><span className="pc-cn">{c.n}</span>
              </button>
            ))}
          </div>
          {cur && cur.id >= 0 && (
            <div className="pc-detail">
              <h3>{cur.label}</h3>
              <div className="pc-muted">{cur.n} {kind === 'record' ? 'books' : 'points'}</div>
              {cur.caption && <p className="pc-caption"><b>Spatial pattern.</b> {cur.caption}</p>}
              {cur.ellipse && <p className="pc-caption"><b>Direction.</b> {pcLeanText(cur.ellipse)} <Link to="/tests-lab">Is this more than chance? →</Link></p>}
              <h4>What defines it</h4>
              <div className="pc-muted pc-small">Share of the cluster's members with this feature vs. everywhere else (XGBoost + SHAP ranking)</div>
              {cur.features.slice(0, 8).map((f) => (
                <div key={f.f} className="pc-feat">
                  <div className="pc-fname">{pretty(f.f)}</div>
                  <div className="pc-bars">
                    <span className="pc-bar in" style={{ width: `${Math.min(100, f.in * 100)}%` }} /><span className="pc-bv">{pct(f.in)}</span>
                    <span className="pc-bar out" style={{ width: `${Math.min(100, f.out * 100)}%` }} /><span className="pc-bv">{pct(f.out)}</span>
                  </div>
                </div>
              ))}
              <h4>Periods covered</h4>
              <div className="pc-eras">
                {cur.eras.map((v, i) => (
                  <div key={i} className="pc-era" title={`${eras[i]}: ${pct(v)}`}>
                    <span style={{ height: `${Math.max(2, v * 100)}%`, background: eraColor(i, eras.length) }} /><em>{eras[i].replace('before ', '<').replace(' on', '+')}</em>
                  </div>
                ))}
              </div>
              {kind !== 'record' && (<><h4>Main places</h4><div className="pc-places">{cur.places.map(([g, n]) => <span key={g} className="pc-chip">{g} <em>{n}</em></span>)}</div></>)}
              <h4>Example titles</h4>
              <ul className="pc-titles">{cur.titles.map((t) => <li key={t}>{t}</li>)}</ul>
            </div>
          )}
          {!cur && <p className="pc-muted pc-small">Pick a cluster to see its defining topics, periods, places and example titles.</p>}
          {!cur && view !== 'topic' && set.overall && <p className="pc-caption"><b>Spatial pattern of everything.</b> {set.overall.caption}</p>}
        </aside>
      </div>

      <details className="pc-method">
        <summary>How the clusters were found</summary>
        <p>
          <b>Features.</b> For every point: the share of its books in each of 22 topic themes; the share carrying each of the ~150 most common subject-heading
          terms (History, Biography, Antiquities, Famine, …); the periods the books are about (10 eras, from before 1000 to 2014 on); and the language mix.
          {kind === 'place_period' && ' In the place × period view the period is one of the strongest features, so the same place appears in several clusters over time.'}
        </p>
        <p>
          <b>Spatial ovals.</b> For each cluster, subject places are weighted by the number of books and projected to kilometres. The oval is a standard deviational
          ellipse (1 SD along the principal axes) of the core — the places within the closest 85% of the books — so a few distant places (diaspora, other countries) do not stretch it.
          Its centre is where the topic is concentrated, its size how widely it is spread, its long axis the main direction of the pattern; the share of books inside is
          printed in the caption. In the by-period view, arrows connect the cluster's centre in successive eras: length = km moved, direction = where attention shifted.
          Dashed ovals are based on fewer than five places and are unreliable.
        </p>
        <p>
          <b>Map and clusters.</b> UMAP (cosine distance) draws the 2-D map; HDBSCAN finds dense groups in a 6-D UMAP of the same data. Points that fit no group stay
          grey. <b>Explanation.</b> XGBoost is then trained to predict each point's cluster from its features; SHAP values rank the features that define each cluster.
          Cross-validated accuracy for this view: <b>{pct(set.cv_accuracy)}</b> — a high value means the clusters are distinguishable from their content,
          but since they were built from the same features it shows consistency, not independent proof.
        </p>
      </details>

      <section className="pc-tests">
        <h2>Is topical coverage divided by region? Four tests</h2>
        <p>
          A popular claim holds that Ukraine is split in two, often along the Dnipro. A library catalogue cannot settle what a country is, but it can show whether
          <i> what is written about places</i> changes sharply across a line. We tested this on the clusters above; every test compares the real data with randomly
          shuffled versions, so a result has to beat chance to count.
        </p>
        <figure className="pc-fig">
          <img src={`${process.env.PUBLIC_URL}/images/spatial_tests_figure.png`} alt="Four panels. 1: observed topic-cluster radius against random place sets, almost no difference. 2: bars showing a region classifier reaching about 0.4 to 0.5 balanced accuracy against 0.25 for guessing. 3: ranking of how well topics separate the two sides of 13 lines; the Dnipro sits in the middle. 4: schematic map of places split by the Dnipro and two example lines." />
          <figcaption>Figure. Tests of regional structure in topical coverage (DK508 catalogue). Scripts: <code>spatial_tests.py</code>, <code>dnipro_test.py</code>.</figcaption>
        </figure>

        <h3>1 · Are topic clusters more compact than random place sets?</h3>
        <p>
          For each cluster we measured the spread of its subject places (effective radius of the oval described above) and compared it with 500–1,000 random sets of places of the
          same size. On the full data, clusters look somewhat tighter than random (typical radius about 130–160 km against 200–225 km). Much of that comes from coarse geocoding: when generic
          &ldquo;Ukraine&rdquo; headings and anything located at Kyiv&rsquo;s coordinates are removed, book clusters spread exactly like random sets (277 km against 276 km). After correcting
          for multiple tests, no by-period or book cluster, and only one small place cluster, differs from chance in size; none of the by-period or book clusters is more elongated than chance. <b>The
          individual oval shapes should therefore not be over-interpreted.</b>
        </p>

        <h3>2 · Can topics tell west, centre, east and south apart?</h3>
        <p>
          A classifier was asked to predict a place&rsquo;s region (west, centre, east, south) from its topic profile alone, and likewise for books that are about a single region. Balanced accuracy is
          about 0.38&ndash;0.47 against 0.25 for guessing, in every variant, and beats shuffled labels (permutation p &le; 0.016). Regions differ in emphasis: the west in WWII and the OUN and UPA underground,
          the east in the Famine (Holodomor), the south in antiquities and Odesa, the centre in general, local and military history and the 1917&ndash;21 revolution. The signal is modest, and some
          of it comes from place names that appear inside subject headings.
        </p>

        <h3>3 · Is the Dnipro a special divide?</h3>
        <p>
          We asked how well topics predict which side of a line a book is about, for the Dnipro (left against right bank) and for 12 other lines across the country, leaving out a 40 km strip around each line.
          The Dnipro reaches 63% (50% is guessing), in the middle of the pack. East&ndash;west lines at 47&ndash;48&deg;N (about 67&ndash;68%, the Black Sea coast against the rest) and north&ndash;south lines at
          24&ndash;26&deg;E (about 65%, the far west against the rest) separate topics better. Every line gives some signal because topics change gradually across space, which is not the same as a sharp break.
        </p>

        <h3>4 · What was compared</h3>
        <p>
          The map shows subject places coloured by side of the Dnipro (an approximate course), with two of the other tested lines dashed. Places within 40 km of the river are excluded from the Dnipro test.
        </p>

        <h3>Finding A · Topic clusters have footprints no more compact or spread than random place sets</h3>
        <p>
          Each topic cluster covers a set of subject places, and the oval above summarises where they lie. The question is whether such a footprint is <i>special</i>. If a topic were tied to
          a particular area, its places would sit closer together than a random handful of places would. If a topic were global to the country, they would spread out like a random handful.
          We drew 500&ndash;1,000 random sets of places with the same number of places as each cluster and compared their typical radius and elongation with the real cluster.
        </p>
        <p>
          The result is that real clusters are, for the most part, indistinguishable from random sets: after correcting for multiple tests, none of the 20&ndash;23 by-period clusters or 48&ndash;51 book
          clusters is reliably more compact, more spread or more elongated than chance, and only one small place cluster (&ldquo;Russian &middot; Ukrainian &middot; Other topics&rdquo;, 65 km against about 250 km) is
          reliably tighter. In plain terms, <b>topics are not confined to their own corner of the country</b>: the same kinds of subject, such as politics, biography, history and local history, are written about
          across many places. The thin or stretched ovals seen on the map (for example 61 &times; 1 km) usually come from clusters with only a few distinct coordinates and should be read as sampling noise.
        </p>

        <h3>Finding B · Regional emphases are real but modest</h3>
        <p>
          Although footprints are not special, topic <i>profiles</i> still carry some information about region. The table lists topics that are noticeably more common in one region than in the others
          (classifier on places and on books about a single region, after removing generic &ldquo;Ukraine&rdquo; places).
        </p>
        <table className="pc-table">
          <thead><tr><th>Region</th><th>Topics over-represented</th><th>Recognised correctly*</th></tr></thead>
          <tbody>
            <tr><td>West</td><td>WWII 1939&ndash;1945; the OUN and UPA nationalist underground; description and travel; biography; ethnic groups</td><td>about 40&ndash;45%</td></tr>
            <tr><td>Centre</td><td>general history; local and military history; Revolution and Civil War 1917&ndash;21; politics and government</td><td>about 40&ndash;50%</td></tr>
            <tr><td>East</td><td>the Famine (Holodomor); sources; headings naming Kharkiv and Poltava</td><td>about 30%</td></tr>
            <tr><td>South</td><td>antiquities; Odesa; ethnic groups and relations; guidebooks</td><td>about 45&ndash;55%</td></tr>
          </tbody>
        </table>
        <p className="pc-muted pc-small">
          * Share of that region&rsquo;s places or books that the classifier assigns correctly (random guessing gives about 25%). The east is the hardest to recognise and the south and west the easiest. Some of
          the signal is place names inside subject headings (Odesa, Kharkiv, Poltava), so the table slightly overstates how much is purely topical.
        </p>
        <p>
          &ldquo;Modest&rdquo; here means overall accuracy of about 0.38&ndash;0.47 against 0.25 for guessing: clearly better than chance (permutation p &le; 0.016), but a classifier still gets more than half of the
          places or books wrong. Regions lean toward certain subjects without being cut off from the rest.
        </p>

        <h3>What this supports, and what it does not</h3>
        <p>
          The tests support a limited statement: <b>topical coverage varies gradually across Ukraine; there is no sharp east&ndash;west or Dnipro break, but regions differ in emphasis</b>,
          most clearly the south and the far west. They do not show whether Ukraine is, or is not, &ldquo;one country&rdquo;. That is a legal, historical and political question, and a catalogue records what
          libraries chose to collect, not what people think.
        </p>
        <p className="pc-muted pc-small">
          Limits: regions are crude boxes; some places are geocoded only to a country or region centroid; heading terms that name places leak region information into the classifier; the
          book-level classifier used 15&ndash;60 shuffles; the Dnipro line is an approximate polyline.
        </p>
      </section>
    </div>
  );
}
