import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import { Panel, C } from './TestsLab';

// Ridge maps of where the books of each period are about. Data: public/data/ridge_lab.json
// (built by scripts/build_ridge_lab.py: kernel densities of the places of located books, with
// the divergence between neighbouring periods tested against shuffled books).

const LABEL = {
  '<1400': 'Before 1400', '1400-1648': '1400-1648', '1648-1800': '1648-1800', '1800-1917': '1800-1917',
  '1917-45': '1917-45', '1945-91': '1945-91', '1991+': '1991 on',
};
const REGION_BOUNDS = { lon: [[26.8, 'west | centre'], [34.5, 'centre | east']], lat: [[47.3, 'south | north']] };

function RidgePanel({ data, axis, V, A, N, noCrimea, cur, setSel, title }) {
  const eras = data.eras;
  const grid = data[axis];
  const gmin = grid[0], gmax = grid[grid.length - 1];
  const W = 620, rowH = 58, m = { l: 96, r: 52, t: 20, b: 34 };
  const H = m.t + m.b + rowH * eras.length + 24;
  const iw = W - m.l - m.r;
  const sx = (v) => m.l + ((v - gmin) / (gmax - gmin)) * iw;
  const peak = Math.max(...eras.map((e) => Math.max(...(V.ridge[axis][e] || [0]))));
  const amp = rowH * 1.45;
  const base = (i) => m.t + 24 + rowH * (i + 1) - 6;
  const pathFor = (ys, b) => `M ${sx(grid[0])} ${b} ` + ys.map((y, k) => `L ${sx(grid[k])} ${b - (y / peak) * amp}`).join(' ') + ` L ${sx(gmax)} ${b} Z`;
  const lineFor = (ys, b) => ys.map((y, k) => `${k ? 'L' : 'M'} ${sx(grid[k])} ${b - (y / peak) * amp}`).join(' ');
  const pairOf = (e) => V.pairs[axis].find((p) => p.b === e);
  const ticks = axis === 'lon' ? [22, 25, 28, 31, 34, 37, 40] : [44, 46, 48, 50, 52];
  const unit = axis === 'lon' ? '°E' : '°N';
  return (
    <div className="tl-col" style={{ flex: '1 1 440px', minWidth: 0 }}>
      <h3>{title}</h3>
      <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label={title}>
        {REGION_BOUNDS[axis].map(([v, lab]) => (
          <g key={v}><line x1={sx(v)} x2={sx(v)} y1={m.t + 14} y2={H - m.b} stroke="#7d8794" strokeDasharray="4 4" opacity="0.6" /><text x={sx(v) + 4} y={m.t + 10} className="tl-tick" textAnchor="start">{lab}</text></g>
        ))}
        {eras.map((e, i) => {
          const ys = V.ridge[axis][e];
          if (!ys) return null;
          const b = base(i), on = e === cur, sparse = V.n[e] < 30;
          const p = pairOf(e);
          return (
            <g key={e} onMouseEnter={() => setSel(e)} onClick={() => setSel(e)} style={{ cursor: 'pointer' }}>
              <rect x={0} y={b - rowH + 6} width={W} height={rowH} fill="transparent" />
              <path d={pathFor(ys, b)} fill={sparse ? C.grey : on ? C.orange : C.blue} opacity={on ? 0.95 : sparse ? 0.45 : 0.6} stroke="#fff" strokeWidth="1" />
              {!noCrimea && N.ridge[axis][e] && <path d={lineFor(N.ridge[axis][e], b)} fill="none" stroke="#e8edf3" strokeWidth="1.1" strokeDasharray="4 3" opacity="0.9" />}
              <polygon points={`${sx(V.mean[axis][e]) - 5},${b + 9} ${sx(V.mean[axis][e]) + 5},${b + 9} ${sx(V.mean[axis][e])},${b + 1}`} fill={C.white} />
              <text x={m.l - 8} y={b - 12} textAnchor="end" className="tl-marklabel" fill={on ? C.white : C.pale}>{LABEL[e]}</text>
              <text x={m.l - 8} y={b + 1} textAnchor="end" className="tl-tick">n={V.n[e]}</text>
              {p && <text x={W - m.r + 8} y={b - rowH / 2 - 4} className="tl-tick" textAnchor="start" fill={p.p < 0.01 ? C.orange : undefined}>{p.jsd.toFixed(2)}{p.p < 0.01 ? '*' : ''}</text>}
            </g>
          );
        })}
        <line x1={m.l} x2={W - m.r} y1={H - m.b} y2={H - m.b} className="tl-grid" />
        {ticks.map((t) => <text key={t} x={sx(t)} y={H - m.b + 15} textAnchor="middle" className="tl-tick">{t}{unit}</text>)}
        <text x={W - m.r + 8} y={m.t + 10} className="tl-tick" textAnchor="start">diverg.</text>
      </svg>
    </div>
  );
}

function MapView({ map, noCrimea, cur, mean }) {
  const k = Math.cos((48.5 * Math.PI) / 180);
  const x0 = 22 * k, x1 = 40.5 * k, y0 = 44, y1 = 52.5;
  const W = 640, H = Math.round((W * (y1 - y0)) / (x1 - x0));
  const sx = (lon) => ((lon * k - x0) / (x1 - x0)) * W;
  const sy = (lat) => H - ((lat - y0) / (y1 - y0)) * H;
  const pts = map.points[noCrimea ? 'nocrimea' : 'all'][cur] || [];
  const sparse = cur === '1945-91';
  const area = (w) => 3 + Math.sqrt(w) * 5.2;
  const ring = (r) => 'M ' + r.map(([la, lo]) => `${sx(lo).toFixed(1)} ${sy(la).toFixed(1)}`).join(' L ') + ' Z';
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label={`Places named by the books of ${LABEL[cur]}`}>
      {map.outline.map((r, i) => <path key={i} d={ring(r)} fill="#1a2029" stroke="#7d8794" strokeWidth="1" />)}
      <polyline points={map.river.map(([la, lo]) => `${sx(lo)},${sy(la)}`).join(' ')} fill="none" stroke="#6aa6d8" strokeWidth="2" opacity="0.8" />
      <line x1={sx(26.8)} x2={sx(26.8)} y1={sy(52.4)} y2={sy(48.2)} stroke="#7d8794" strokeDasharray="4 4" opacity="0.6" />
      <line x1={sx(34.5)} x2={sx(34.5)} y1={sy(52.4)} y2={sy(44.2)} stroke="#7d8794" strokeDasharray="4 4" opacity="0.6" />
      <line x1={sx(29)} x2={sx(40.3)} y1={sy(47.3)} y2={sy(47.3)} stroke="#7d8794" strokeDasharray="4 4" opacity="0.6" />
      {pts.map(([la, lo, w], i) => <circle key={i} cx={sx(lo)} cy={sy(la)} r={area(w)} fill={sparse ? C.grey : C.orange} opacity="0.55" stroke="#fff" strokeWidth="0.6"><title>{`${w.toFixed(1)} books`}</title></circle>)}
      {mean && <polygon points={`${sx(mean[1]) - 7},${sy(mean[0]) - 10} ${sx(mean[1]) + 7},${sy(mean[0]) - 10} ${sx(mean[1])},${sy(mean[0])}`} fill={C.white} stroke="#000" strokeWidth="1" />}
      <text x="10" y="22" className="tl-marklabel" fill={C.white}>{LABEL[cur]}</text>
    </svg>
  );
}

const DIR_COL = { Moscow: C.orange, Warsaw: C.blue, neither: '#7b8088', round: '#2a313b' };
const DIR_TEXT = { Moscow: 'leans towards Moscow', Warsaw: 'leans towards Warsaw', neither: 'elongated, towards neither', round: 'nearly round, no direction' };
const SHORT = { 'Soviet Union': 'USSR', 'Russia (Federation)': 'Russia', 'Muscovy (Grand Duchy)': 'Muscovy', 'Kievan Rus': 'Kyiv Rus', 'Zaporozhian Sich': 'Sich', 'Donbas (Region)': 'Donbas', 'Crimean Khanate': 'Crim. Khanate' };
const shortName = (n) => SHORT[n] || (n.length > 12 ? n.slice(0, 11) + '…' : n);

function DirectionByPeriod({ map }) {
  const [data, setData] = useState(null);
  const [per, setPer] = useState('1991+');
  const [show, setShow] = useState('core');
  const [tip, setTip] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/direction_by_period.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch(() => {});
    return () => { off = true; };
  }, []);
  const rows = React.useMemo(() => {
    if (!data) return [];
    const all = Object.entries(data.cells).map(([name, cs]) => {
      const q = data.eras.filter((e) => cs[e]);
      return { name, cs, q: q.length, mos: q.filter((e) => cs[e].lc === 'Moscow').length, books: q.reduce((s, e) => s + cs[e].n, 0) };
    });
    const f = show === 'all' ? all : show === 'moscow' ? all.filter((r) => r.mos >= 1) : all.filter((r) => r.q >= 4 && r.mos >= 2);
    return f.sort((a, b) => b.books - a.books);
  }, [data, show]);
  if (!data) return null;
  const move = (e, d, era, name) => setTip({ x: e.clientX, y: e.clientY, d, era, name });
  return (
    <Panel n="2" title="How does the direction of a heading's oval change from period to period?"
      lead="Each cell is the oval of the books under one subject heading whose place entries refer to one period. Colour is the direction of its long axis (within 22.5° of the bearing from the oval's centre to Moscow or Warsaw), the label is the place that the most books name, then how many times as long as wide the oval is and how many books there are. Hover a cell for its details.">
      <div className="tl-toolbar">
        <label>Headings <select value={show} onChange={(e) => setShow(e.target.value)}>
          <option value="core">With at least four periods and two towards Moscow</option>
          <option value="moscow">Towards Moscow in at least one period</option>
          <option value="all">All that can be drawn in at least one period</option>
        </select></label>
        <span className="tl-muted">{rows.length} headings</span>
      </div>
      <div className="tl-tablewrap" style={{ maxHeight: 520, maxWidth: '100%' }}>
        <table className="tl-table" style={{ borderCollapse: 'separate', borderSpacing: 2 }}>
          <thead><tr><th style={{ position: 'sticky', left: 0, background: 'var(--surface-1, #0d1117)' }}>Subject heading</th>{data.eras.map((e) => <th key={e} style={{ textAlign: 'center' }}>{LABEL[e]}</th>)}</tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.name}>
                <td style={{ position: 'sticky', left: 0, background: 'var(--surface-1, #0d1117)', whiteSpace: 'nowrap', paddingRight: 12 }}>{r.name}</td>
                {data.eras.map((e) => {
                  const d = r.cs[e];
                  if (!d) return <td key={e} style={{ minWidth: 92, border: '1px solid #232a33' }} />;
                  const light = d.lc === 'Moscow' || d.lc === 'Warsaw';
                  return (
                    <td key={e} tabIndex={0} onMouseEnter={(ev) => move(ev, d, e, r.name)} onMouseMove={(ev) => move(ev, d, e, r.name)} onMouseLeave={() => setTip(null)}
                      onFocus={(ev) => { const b = ev.currentTarget.getBoundingClientRect(); setTip({ x: b.left + 10, y: b.bottom, d, era: e, name: r.name }); }} onBlur={() => setTip(null)}
                      style={{ minWidth: 92, textAlign: 'center', background: DIR_COL[d.lc], color: light ? '#fff' : '#d6d9de', borderRadius: 3, padding: '3px 4px', lineHeight: 1.25, cursor: 'default' }}>
                      <div style={{ fontWeight: 600, fontSize: 12 }}>{shortName(d.top[0])}</div>
                      <div style={{ fontSize: 10.5, opacity: 0.9 }}>{d.el}× · {d.n.toLocaleString()} books</div>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="tl-legend" style={{ display: 'flex', flexWrap: 'wrap', gap: '6px 16px', fontSize: 12, margin: '10px 0' }}>
        {Object.keys(DIR_COL).map((k) => <span key={k}><span style={{ display: 'inline-block', width: 11, height: 11, background: DIR_COL[k], borderRadius: 2, marginRight: 6, verticalAlign: '-1px' }} />{DIR_TEXT[k]}</span>)}
        <span><span style={{ display: 'inline-block', width: 11, height: 11, border: '1px solid #232a33', borderRadius: 2, marginRight: 6, verticalAlign: '-1px' }} />fewer than 8 books or 6 places</span>
      </div>
      {map && (() => {
        const k = Math.cos((48.5 * Math.PI) / 180);
        const x0 = 22 * k, x1 = 40.5 * k, y0 = 44, y1 = 52.5;
        const W = 640, H = Math.round((W * (y1 - y0)) / (x1 - x0));
        const sx = (lon) => ((lon * k - x0) / (x1 - x0)) * W;
        const sy = (lat) => H - ((lat - y0) / (y1 - y0)) * H;
        const kmPx = H / ((y1 - y0) * 110.57);
        const ring = (r) => 'M ' + r.map(([la, lo]) => `${sx(lo).toFixed(1)} ${sy(la).toFixed(1)}`).join(' L ') + ' Z';
        const ov = [];
        Object.entries(data.cells).forEach(([name, cs]) => { const d = cs[per]; if (d) ov.push({ name, d }); });
        ov.sort((a, b) => a.d.n - b.d.n);
        const T = data.tests[per];
        const row = (lab, t) => t && <tr key={lab}><td>{lab}</td><td><b>{t[0]}</b></td><td>{t[1]}</td><td>{t[2] < 0.01 ? t[2].toFixed(3) : t[2].toFixed(2)}</td></tr>;
        return (
          <div className="tl-row" style={{ marginTop: 14 }}>
            <div className="tl-col" style={{ flex: '1 1 380px', minWidth: 0, maxWidth: 640 }}>
              <h3>The ovals of the period</h3>
              <div className="tl-btns" style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
                {data.eras.map((e) => <button key={e} type="button" onClick={() => setPer(e)} aria-pressed={per === e} style={{ fontWeight: per === e ? 700 : 400, outline: per === e ? '2px solid #7fb3ff' : 'none' }}>{LABEL[e]}</button>)}
              </div>
              <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label={`Ovals of the subject headings of ${LABEL[per]}`}>
                {map.outline.map((r, i) => <path key={i} d={ring(r)} fill="#1a2029" stroke="#7d8794" strokeWidth="1" />)}
                <polyline points={map.river.map(([la, lo]) => `${sx(lo)},${sy(la)}`).join(' ')} fill="none" stroke="#6aa6d8" strokeWidth="2" opacity="0.6" />
                {ov.map(({ name, d }) => {
                  const [la, lo, a, b] = d.oval;
                  const round = d.lc === 'round';
                  return (
                    <ellipse key={name} cx={sx(lo)} cy={sy(la)} rx={a * kmPx} ry={b * kmPx} transform={`rotate(${d.b - 90} ${sx(lo)} ${sy(la)})`}
                      fill={DIR_COL[d.lc]} fillOpacity={round ? 0.04 : 0.12} stroke={round ? '#8b929b' : DIR_COL[d.lc]} strokeWidth={round ? 0.8 : 1.6} strokeDasharray={round ? '3 3' : undefined} strokeOpacity={round ? 0.5 : 0.9}
                      onMouseEnter={(ev) => move(ev, d, per, name)} onMouseMove={(ev) => move(ev, d, per, name)} onMouseLeave={() => setTip(null)} />
                  );
                })}
                <text x="10" y="22" className="tl-marklabel" fill={C.white}>{LABEL[per]}</text>
              </svg>
              <p className="tl-note">One oval for each heading with at least 8 books and 6 places in the period: solid where the oval is at least 1.5 times as long as wide (orange towards Moscow, blue towards Warsaw, grey towards neither), dashed and faint where it is nearly round. Hover an oval for its heading.</p>
            </div>
            <div className="tl-col" style={{ flex: '1 1 300px' }}>
              <div className="tl-readout">
                <h3>{LABEL[per]}</h3>
                {T ? (<>
                  <p><b>{T.elong}</b> of the {ov.length} headings drawn here are elongated enough to have a direction. Counted against random place sets of the same period and sizes:</p>
                  <table className="tl-table"><thead><tr><th>Towards</th><th>Observed</th><th>Expected</th><th>p</th></tr></thead><tbody>{row('Moscow (nearer of Moscow and Istanbul)', T.moscow)}{row('Istanbul (nearer)', T.istanbul)}{row('Warsaw', T.warsaw)}</tbody></table>
                  <p className="tl-note">The test is on the counts. No single oval is significant on its own after correcting for the number of headings, so the ovals drawn are those that make up the counts, not individually significant ones.</p>
                </>) : <p className="tl-muted">Too few headings in this period have enough books and places for a direction count to be meaningful.</p>}
              </div>
            </div>
          </div>
        );
      })()}
      <p className="tl-note">The book count is every book under the heading in that period, whether or not it names a located place; the oval is drawn from the places of those that do, weighted by the number of books naming each. These are descriptive comparisons on small numbers of books and are not tested against random place sets. The tested counts are in the paper.</p>
      {tip && (
        <div role="tooltip" style={{ position: 'fixed', left: Math.min(tip.x + 14, window.innerWidth - 300), top: Math.min(tip.y + 14, window.innerHeight - 260), width: 300, background: '#161b22', color: '#e6e9ee', border: '1px solid #3a424d', borderRadius: 8, padding: '9px 11px', fontSize: 12, lineHeight: 1.4, boxShadow: '0 6px 20px rgba(0,0,0,.45)', pointerEvents: 'none', zIndex: 50 }}>
          <div style={{ fontWeight: 700, marginBottom: 2 }}>{tip.name}, {LABEL[tip.era]}</div>
          <div style={{ color: DIR_COL[tip.d.lc] === '#2a313b' ? '#aab1bb' : DIR_COL[tip.d.lc] }}>{DIR_TEXT[tip.d.lc]}</div>
          <div>{tip.d.n.toLocaleString()} books, {tip.d.k} places; oval {tip.d.el}× as long as wide, long axis {tip.d.b}° from north{tip.d.el < 1.5 ? ' (too round for the direction to count)' : ''}.</div>
          {tip.d.pub && (
            <div style={{ marginTop: 6 }}>
              Published {tip.d.pub[0]}–{tip.d.pub[4]}, median {tip.d.pub[2]} (middle half {tip.d.pub[1]}–{tip.d.pub[3]}; {tip.d.pub[8]} books with a date).
              <div style={{ display: 'flex', height: 8, borderRadius: 4, overflow: 'hidden', margin: '5px 0 2px', background: '#2a313b' }} aria-hidden="true">
                <div style={{ width: `${tip.d.pub[5]}%`, background: '#8b929b' }} />
                <div style={{ width: `${tip.d.pub[6]}%`, background: '#3987e5' }} />
                <div style={{ width: `${tip.d.pub[7]}%`, background: '#d95926' }} />
              </div>
              <span style={{ color: '#aab1bb' }}>{tip.d.pub[5]}% before 1991 · {tip.d.pub[6]}% 1991–2013 · {tip.d.pub[7]}% 2014 on</span>
            </div>
          )}
          <div style={{ marginTop: 4 }}>Most named: {tip.d.top.join('; ')}.</div>
        </div>
      )}
    </Panel>
  );
}

function Ridges({ data, map }) {
  const [noCrimea, setNoCrimea] = useState(false);
  const [sel, setSel] = useState('1800-1917');
  const A = data.variants.all, N = data.variants.nocrimea;
  const V = noCrimea ? N : A;
  const cur = sel;
  const rg = V.regions[cur] || {};
  const con = !noCrimea && (data.concentration || {})[cur];
  const conNote = con ? <p className="tl-note">This period has <b>{con.about.toLocaleString()}</b> books in the catalog, but only {V.n[cur]} of them name a place that can be located; the rest name only Ukraine as a whole. Those books name <b>{con.places}</b> different places, yet the five largest carry <b>{con.top5}%</b> of the weight (largest: {con.top.join('; ')}). Ridges and means weight each place by the number of books that name it, so a few large places set where the ridge peaks and the many small circles barely move it.</p> : null;
  const prL = V.pairs.lon.find((p) => p.b === cur), prT = V.pairs.lat.find((p) => p.b === cur);
  const sent = (pr, what) => pr && <>{what}: <b>{pr.jsd.toFixed(3)}</b> bits from {LABEL[pr.a]} (shuffled books give {pr.null.toFixed(3)} on average; {pr.p < 0.01 ? 'fewer than 1% of 300 shuffles reached this' : `${Math.round(pr.p * 100)}% of 300 shuffles reached this, so it is within chance`}). </>;
  return (
    <Panel n="1" title="Do the books of each period sit in the same part of the country?"
      lead="Each ridge shows where the places that the books of one period are about lie, from west to east (left) and from south to north (right). A taller ridge means more books. If the country were splitting, the ridges would break into separate peaks that move apart. If attention only moves about, the ridges stay joined and their centre shifts. The number to the right of each ridge is how far it differs from the period above (Jensen-Shannon divergence, in bits); a star means more than shuffled books give. Hover over or click a ridge for its numbers.">
      <div className="tl-toolbar">
        <label className="tl-grow"><input type="checkbox" checked={noCrimea} onChange={(e) => setNoCrimea(e.target.checked)} /> Leave out books about Crimea</label>
      </div>
      <div className="tl-row">
        <RidgePanel data={data} axis="lon" V={V} A={A} N={N} noCrimea={noCrimea} cur={cur} setSel={setSel} title="a  West to east" />
        <RidgePanel data={data} axis="lat" V={V} A={A} N={N} noCrimea={noCrimea} cur={cur} setSel={setSel} title="b  South to north" />
      </div>
      <p className="tl-note">Triangle: mean position. {noCrimea ? 'Books about Crimea are left out and each ridge is rescaled.' : 'Dashed line: the same ridge without Crimea, rescaled.'} Orange: the period you are pointing at. 1945-91 has 23 books and is drawn in grey; its ridge is not interpreted.</p>
      {map && (
        <div className="tl-row">
          <div className="tl-col" style={{ flex: '1 1 380px', minWidth: 0, maxWidth: 640 }}>
            <h3>The same places on the map</h3>
            <MapView map={map} noCrimea={noCrimea} cur={cur} mean={[V.mean.lat[cur], V.mean.lon[cur]]} />
            <p className="tl-note">Each circle is a place that the books of the period are about; its area shows how many books. The triangle is the mean position, the blue line the Dnipro, the dashed lines the boundaries of the four region boxes. Point at a ridge above to change the period.</p>
          </div>
          <div className="tl-col" style={{ flex: '1 1 300px' }}>
            <div className="tl-readout">
              <h3>{LABEL[cur]}</h3>
              <p><b>{V.n[cur]}</b> located books. Their places average <b>{V.mean.lon[cur].toFixed(1)}°E</b> and <b>{V.mean.lat[cur].toFixed(1)}°N</b>. By region: west <b>{((V.regions[cur] || {}).west || 0).toFixed(0)}%</b>, centre <b>{((V.regions[cur] || {}).centre || 0).toFixed(0)}%</b>, east <b>{((V.regions[cur] || {}).east || 0).toFixed(0)}%</b>, south <b>{((V.regions[cur] || {}).south || 0).toFixed(0)}%</b> of their place mentions.</p>
              {conNote}
              {prL ? <p>{sent(prL, 'West-east')}{sent(prT, 'South-north')}</p> : <p className="tl-muted">This is the first period, so there is nothing to compare it with.</p>}
            </div>
          </div>
        </div>
      )}
      {!map && <div className="tl-readout">
        <h3>{LABEL[cur]}</h3>
        <p><b>{V.n[cur]}</b> located books. Their places average <b>{V.mean.lon[cur].toFixed(1)}°E</b> and <b>{V.mean.lat[cur].toFixed(1)}°N</b>. By region: west <b>{(rg.west || 0).toFixed(0)}%</b>, centre <b>{(rg.centre || 0).toFixed(0)}%</b>, east <b>{(rg.east || 0).toFixed(0)}%</b>, south <b>{(rg.south || 0).toFixed(0)}%</b> of their place mentions.</p>
              {conNote}
        {prL ? <p>{sent(prL, 'West-east')}{sent(prT, 'South-north')}</p> : <p className="tl-muted">This is the first period, so there is nothing to compare it with.</p>}
      </div>}
      <div className="tl-readout">
        <p className="tl-note">The ridges of neighbouring periods overlap and do not part into separate peaks, and even the largest divergence is well short of the 1 bit that two ridges with no overlap would give. Before 1400 the books are about the Black Sea coast and Kyivan Rus; in 1800-1917 the west holds 41% of the place mentions, against 12% in 1648-1800 (Lviv, Transcarpathia, Volhynia, Bukovina); from 1991 the south holds 60%, and most of that rise is Crimea. Tick the box above to see the 1991 rise shrink.</p>
      </div>
    </Panel>
  );
}

export default function DriftLab() {
  const [data, setData] = useState(null);
  const [map, setMap] = useState(null);
  const [error, setError] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/ridge_lab.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    fetch(`${process.env.PUBLIC_URL}/data/ridge_map.json`).then((r) => r.json()).then((d) => { if (!off) setMap(d); }).catch((e) => console.error(e));
    return () => { off = true; };
  }, []);
  return (
    <div className="tl-root">
      <p className="tl-back"><Link to="/tests-lab">← Tests lab</Link></p>
      <h1>Drift lab: does the footprint of the class move or split?</h1>
      <p className="tl-sub">Drift here means that the part of the country the books are about changes from one period to the next. These ridge maps show where the footprint lies in each period, how far it moves, and whether it breaks into separate parts. Click a ridge for its numbers.</p>
      {error && <p className="tl-err">The data file could not be loaded.</p>}
      {!data && !error && <p className="tl-muted">Loading…</p>}
      {data && <Ridges data={data} map={map} />}
      {data && <DirectionByPeriod map={map} />}
    </div>
  );
}
